-- ════════════════════════════════════════════════════════════════════════════
-- qztgo 全库初始化脚本(地基): 全部表结构 + 种子/配置/官网内容数据
-- 来源: 生产库 qztgo DBX 全量导出(2026-11-11),已按 docs/sql/README.md 口径脱敏:
--   · 剔除运行日志/流水: sys_job_log/sys_operation_log/sys_login_log/sys_field_change_log/sys_llm_usage/cms_track_event/cms_push_log/oa_message/sys_attachment/cloud_file/geo_run/geo_result/geo_source/kb_document/oa_notice/stage_record
--   · 剔除业务运行数据: 审批实例/任务/记录、CRM 业务记录(线索/客户/联系人/商机/合同/回款/跟进/工单)、HRM(员工/候选人/考勤/绩效/招聘)、OA(报销/出差/借款/日志/日程/会议预订/表单数据)、PSI 全部单据、商城订单、财务凭证/应收应付/发票、项目/任务、每记录自定义字段值(customer_field/lead_field 及 *_blob)
--   · 剔除含真实密钥的表数据: sys_oauth_config(企微/服务号 secret)/sys_storage_config(OSS AK/SK)/sys_api_key/marketing_account/open_webhook/console_accounts —— 部署后在后台重新配置
--   · admin 种子密码 = 123456(演示密码),首次登录后必须立即修改;其手机/邮箱/企微ID/头像已置空
--   · 保留: 全部 DDL + 地基种子(角色/用户/菜单/API/字典/casbin/定时任务) + 配置(公海/阶段/科目/组织/表单模板/合同模板/自定义字段定义/GEO 题目与平台) + 官网 CMS 内容 + 审批流定义 + 演示账号(密码 123456)
-- 执行: 首次初始化直接全量导入本文件(自带 CREATE DATABASE/USE);增量升级对照 docs/sql/README.md 索引
-- ════════════════════════════════════════════════════════════════════════════

SET NAMES utf8mb4;
-- Database setup
CREATE DATABASE IF NOT EXISTS `qztgo` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `qztgo`;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `approval_add_sign_task`;

CREATE TABLE `approval_add_sign_task` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '加签类型(BEFORE前加签/AFTER后加签)',
  `task_id` bigint unsigned NOT NULL COMMENT '新加签生成的任务ID',
  `sign_task_id` bigint unsigned NOT NULL COMMENT '被加签的原任务ID',
  `root_task_id` bigint unsigned DEFAULT NULL COMMENT '加签链根任务ID',
  `sort` bigint NOT NULL COMMENT '加签顺序',
  `comment` text COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_approval_add_sign_task_task_id` (`task_id`),
  KEY `idx_approval_add_sign_task_sign_task_id` (`sign_task_id`),
  KEY `idx_approval_add_sign_task_root_task_id` (`root_task_id`),
  KEY `idx_approval_add_sign_task_created_at` (`created_at`),
  KEY `idx_approval_add_sign_task_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='加签任务';

DROP TABLE IF EXISTS `approval_flow`;

CREATE TABLE `approval_flow` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `current_version_id` bigint unsigned DEFAULT NULL COMMENT '当前激活版本ID',
  `number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程编号',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '流程名称',
  `form_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表单类型(CONTRACT/QUOTATION/ORDER/INVOICE)',
  `form_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '表单标识(OA_CUSTOM 按模板细分,空=通用)',
  `create_execute` tinyint DEFAULT '1' COMMENT '新建触发(1启用0禁用)',
  `update_execute` tinyint DEFAULT '1' COMMENT '更新触发',
  `submitter_can_revoke` tinyint DEFAULT '1' COMMENT '提交人可撤回',
  `allow_batch_process` tinyint DEFAULT '0' COMMENT '允许批量处理',
  `allow_withdraw` tinyint DEFAULT '0' COMMENT '允许撤回',
  `allow_add_sign` tinyint DEFAULT '0' COMMENT '允许加签',
  `duplicate_approver_rule` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'FIRST_ONLY' COMMENT '重复审批人规则',
  `require_comment` tinyint DEFAULT '0' COMMENT '强制备注',
  `enable` tinyint DEFAULT '1' COMMENT '启用(1是0否)',
  `status_permissions` text COLLATE utf8mb4_unicode_ci COMMENT '基于业务状态的字段权限JSON',
  `description` varchar(3000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  `is_preset` tinyint DEFAULT '0' COMMENT '系统预置(1是0否),预置流程不可删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_flow_form_type` (`form_type`,`form_key`),
  KEY `idx_approval_flow_enable` (`enable`),
  KEY `idx_approval_flow_created_at` (`created_at`),
  KEY `idx_approval_flow_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='流程主表';


DROP TABLE IF EXISTS `approval_flow_version`;

CREATE TABLE `approval_flow_version` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `flow_id` bigint unsigned NOT NULL COMMENT '所属流程ID',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_approval_flow_version_flow_id` (`flow_id`),
  KEY `idx_approval_flow_version_created_at` (`created_at`),
  KEY `idx_approval_flow_version_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='流程版本';


DROP TABLE IF EXISTS `approval_instance`;

CREATE TABLE `approval_instance` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `flow_version_id` bigint unsigned NOT NULL COMMENT '流程版本ID',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表单类型(CONTRACT/QUOTATION/...)',
  `resource_id` bigint unsigned NOT NULL COMMENT '业务资源ID',
  `submitter_id` bigint unsigned NOT NULL COMMENT '提交人ID',
  `current_node_id` bigint unsigned DEFAULT NULL COMMENT '当前节点ID',
  `approval_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '审批状态(PENDING/APPROVING/APPROVED/...)',
  `submit_time` datetime DEFAULT NULL COMMENT '提审时间',
  `approval_time` datetime DEFAULT NULL COMMENT '审批完成时间',
  `execute_timing` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '触发时机(CREATE/UPDATE/DELETE)',
  `comment` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `update_fields` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本次更新字段(逗号分隔)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_approval_instance_flow_version_id` (`flow_version_id`),
  KEY `idx_instance_resource` (`type`,`resource_id`),
  KEY `idx_approval_instance_submitter_id` (`submitter_id`),
  KEY `idx_approval_instance_created_at` (`created_at`),
  KEY `idx_approval_instance_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=235 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='业务资源提审实例';


DROP TABLE IF EXISTS `approval_node`;

CREATE TABLE `approval_node` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `flow_version_id` bigint unsigned NOT NULL COMMENT '所属版本ID',
  `number` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '节点编号',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '节点名称',
  `node_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '节点类型(START/APPROVER/CONDITION/DEFAULT/END)',
  `execute_timing` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '触发时机(CREATE/UPDATE/DELETE)',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_approval_node_flow_version_id` (`flow_version_id`),
  KEY `idx_approval_node_created_at` (`created_at`),
  KEY `idx_approval_node_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=106 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='审批节点';


DROP TABLE IF EXISTS `approval_node_approver`;

CREATE TABLE `approval_node_approver` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT 'PK=approval_node.id(共享主键)',
  `flow_version_id` bigint unsigned NOT NULL COMMENT '所属流程版本ID',
  `approval_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'AUTO_PASS' COMMENT '审批类型',
  `multi_approver_mode` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '多审批人模式(ALL/ANY/SEQUENTIAL)',
  `empty_approver_action` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'AUTO_PASS' COMMENT '空审批人处理',
  `fallback_approver` bigint unsigned DEFAULT NULL COMMENT '兜底审批人ID',
  `same_submitter_action` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'SKIP' COMMENT '提交人本人处理(SKIP/ALLOW/ASSIGN_SUPERIOR)',
  `approver_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批人类型(MEMBER/SUPERIOR/ROLE 等)',
  `approver_direction` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'BOTTOM_UP' COMMENT '解析方向',
  `cc_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '抄送人类型',
  `cc_list` text COLLATE utf8mb4_unicode_ci COMMENT '抄送人JSON数组',
  `approver_list` text COLLATE utf8mb4_unicode_ci COMMENT '审批人JSON数组(按approver_type不同解析)',
  `pass_post_config` text COLLATE utf8mb4_unicode_ci COMMENT '通过后操作配置JSON(字段更新+webhook)',
  `reject_post_config` text COLLATE utf8mb4_unicode_ci COMMENT '驳回后操作配置JSON',
  `field_permissions` text COLLATE utf8mb4_unicode_ci COMMENT '字段权限JSON数组',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_approval_node_approver_flow_version_id` (`flow_version_id`),
  KEY `idx_approval_node_approver_created_at` (`created_at`),
  KEY `idx_approval_node_approver_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=105 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='节点审批人配置(PK 与 ApprovalNode 共享主键)';


DROP TABLE IF EXISTS `approval_node_condition`;

CREATE TABLE `approval_node_condition` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT 'PK=approval_node.id(共享主键)',
  `flow_version_id` bigint unsigned NOT NULL COMMENT '所属流程版本ID',
  `condition_config` text COLLATE utf8mb4_unicode_ci COMMENT '条件配置JSON(分支匹配规则)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_approval_node_condition_flow_version_id` (`flow_version_id`),
  KEY `idx_approval_node_condition_created_at` (`created_at`),
  KEY `idx_approval_node_condition_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=76 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='节点条件配置(PK 与 ApprovalNode 共享主键)';


DROP TABLE IF EXISTS `approval_node_link`;

CREATE TABLE `approval_node_link` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `flow_version_id` bigint unsigned NOT NULL COMMENT '所属版本ID',
  `from_node_id` bigint unsigned NOT NULL COMMENT '起始节点ID',
  `to_node_id` bigint unsigned NOT NULL COMMENT '目标节点ID',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_approval_node_link_flow_version_id` (`flow_version_id`),
  KEY `idx_approval_node_link_from_node_id` (`from_node_id`),
  KEY `idx_approval_node_link_created_at` (`created_at`),
  KEY `idx_approval_node_link_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='节点连线(流转路径)';


DROP TABLE IF EXISTS `approval_record`;

CREATE TABLE `approval_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `instance_id` bigint unsigned NOT NULL COMMENT '实例ID',
  `task_id` bigint unsigned DEFAULT NULL COMMENT '任务ID(自动通过/拒绝可空)',
  `node_id` bigint unsigned NOT NULL COMMENT '节点ID',
  `node_round` bigint NOT NULL COMMENT '节点轮次',
  `result` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批结果(含AUTO_APPROVED/AUTO_UNAPPROVED合成态)',
  `comment` text COLLATE utf8mb4_unicode_ci COMMENT '审批意见',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_approval_record_instance_id` (`instance_id`),
  KEY `idx_approval_record_created_at` (`created_at`),
  KEY `idx_approval_record_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=206 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='审批操作记录(不可变审计日志)';


DROP TABLE IF EXISTS `approval_return_back_record`;

CREATE TABLE `approval_return_back_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `instance_id` bigint unsigned NOT NULL COMMENT '实例ID',
  `task_id` bigint unsigned NOT NULL COMMENT '触发退回的任务ID',
  `return_to_node_id` bigint unsigned NOT NULL COMMENT '退回到的节点ID',
  `return_reason` text COLLATE utf8mb4_unicode_ci COMMENT '退回原因',
  `return_user_id` bigint unsigned NOT NULL COMMENT '退回操作人ID',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_approval_return_back_record_instance_id` (`instance_id`),
  KEY `idx_approval_return_back_record_created_at` (`created_at`),
  KEY `idx_approval_return_back_record_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='退回记录';

DROP TABLE IF EXISTS `approval_task`;

CREATE TABLE `approval_task` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `node_id` bigint unsigned NOT NULL COMMENT '节点ID',
  `node_round` bigint NOT NULL COMMENT '节点轮次(退回重审递增,软删置-1)',
  `instance_id` bigint unsigned NOT NULL COMMENT '实例ID',
  `approver_id` bigint unsigned NOT NULL COMMENT '审批人ID',
  `delegator_id` bigint unsigned DEFAULT NULL COMMENT '上一手审批人(转办让渡/委托代审留痕,委托时=原审批人)',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务状态(PENDING/APPROVING/APPROVED/UNAPPROVED/REVOKED)',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务类型(CC抄送/SN加签/BK退回/NL常规)',
  `action` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批动作(APPROVE/REJECT/SIGN/BACK/REVOKE)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_task_instance_node` (`node_id`,`instance_id`),
  KEY `idx_task_approver` (`approver_id`),
  KEY `idx_approval_task_created_at` (`created_at`),
  KEY `idx_approval_task_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=194 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='审批任务(待办)';


DROP TABLE IF EXISTS `casbin_rule`;

CREATE TABLE `casbin_rule` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `ptype` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v0` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v1` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v2` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v3` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v4` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v5` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_casbin_rule` (`ptype`,`v0`,`v1`,`v2`,`v3`,`v4`,`v5`)
) ENGINE=InnoDB AUTO_INCREMENT=1503 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Casbin权限规则表(RBAC策略)';















DROP TABLE IF EXISTS `cloud_file`;

CREATE TABLE `cloud_file` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `parent_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '父文件夹ID(0=根)',
  `name` varchar(255) NOT NULL COMMENT '文件/文件夹名',
  `is_dir` tinyint NOT NULL DEFAULT '0' COMMENT '0=文件 1=文件夹',
  `object_key` varchar(500) DEFAULT '' COMMENT 'OSS存储路径',
  `url` varchar(1000) DEFAULT '' COMMENT '访问URL',
  `size` bigint NOT NULL DEFAULT '0' COMMENT '文件大小(字节)',
  `content_type` varchar(100) DEFAULT '' COMMENT 'MIME类型',
  `scope` varchar(20) NOT NULL DEFAULT 'personal' COMMENT '权限(personal/dept/public)',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '归属人(personal时用)',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '归属部门(dept时用)',
  `creator_id` bigint unsigned NOT NULL COMMENT '上传/创建人',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1正常 0回收站',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_cloud_parent` (`parent_id`),
  KEY `idx_cloud_scope` (`scope`),
  KEY `idx_cloud_owner` (`owner_id`),
  KEY `idx_cloud_dept` (`dept_id`),
  KEY `idx_cloud_status` (`status`),
  KEY `idx_cloud_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业网盘文件';


DROP TABLE IF EXISTS `cms_article`;

CREATE TABLE `cms_article` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL别名',
  `summary` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '摘要',
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '正文',
  `cover_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图URL',
  `category_id` bigint unsigned DEFAULT NULL COMMENT '分类ID',
  `author_id` bigint unsigned DEFAULT NULL COMMENT '作者用户ID',
  `author_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '作者昵称(快照)',
  `status` tinyint DEFAULT '0' COMMENT '0草稿 1已发布',
  `publish_at` datetime(3) DEFAULT NULL COMMENT '定时发布时间(NULL=立即)',
  `expire_at` datetime(3) DEFAULT NULL COMMENT '内容有效期至(NULL=永久)',
  `is_top` tinyint DEFAULT '0' COMMENT '0否 1置顶',
  `is_hot` tinyint DEFAULT '0' COMMENT '0否 1热门',
  `view_count` bigint DEFAULT '0' COMMENT '浏览量',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_cms_article_slug` (`slug`),
  KEY `idx_cms_article_category_id` (`category_id`),
  KEY `idx_cms_article_author_id` (`author_id`),
  KEY `idx_cms_article_status` (`status`),
  KEY `idx_cms_article_created_at` (`created_at`),
  KEY `idx_cms_article_deleted_at` (`deleted_at`),
  KEY `idx_cms_article_publish_at` (`publish_at`),
  FULLTEXT KEY `ft_cms_article_search` (`title`,`summary`,`content`) /*!50100 WITH PARSER `ngram` */ ,
  CONSTRAINT `fk_cms_article_category` FOREIGN KEY (`category_id`) REFERENCES `cms_category` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文章';


DROP TABLE IF EXISTS `cms_article_tag`;

CREATE TABLE `cms_article_tag` (
  `cms_article_id` bigint unsigned NOT NULL COMMENT '文章ID',
  `cms_tag_id` bigint unsigned NOT NULL COMMENT '标签ID',
  PRIMARY KEY (`cms_article_id`,`cms_tag_id`),
  KEY `fk_cms_article_tag_cms_tag` (`cms_tag_id`),
  CONSTRAINT `fk_cms_article_tag_cms_article` FOREIGN KEY (`cms_article_id`) REFERENCES `cms_article` (`id`),
  CONSTRAINT `fk_cms_article_tag_cms_tag` FOREIGN KEY (`cms_tag_id`) REFERENCES `cms_tag` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CMS文章-标签关联表';

DROP TABLE IF EXISTS `cms_article_version`;

CREATE TABLE `cms_article_version` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `article_id` bigint unsigned NOT NULL COMMENT '文章ID',
  `version_no` int NOT NULL COMMENT '版本号(每篇递增)',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '标题快照',
  `summary` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '摘要快照',
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '正文快照',
  `cover_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '封面快照',
  `editor_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '快照时操作人ID',
  `editor_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '快照时操作人昵称',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '软删除',
  PRIMARY KEY (`id`),
  KEY `idx_cav_article` (`article_id`,`version_no`),
  KEY `idx_cav_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CMS 文章修订版本快照';

DROP TABLE IF EXISTS `cms_category`;

CREATE TABLE `cms_category` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `parent_id` bigint unsigned DEFAULT '0' COMMENT '父分类ID(0为根)',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类名称',
  `slug` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL别名',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `status` tinyint DEFAULT '1' COMMENT '1启用 0禁用',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_cms_category_slug` (`slug`),
  KEY `idx_cms_category_parent_id` (`parent_id`),
  KEY `idx_cms_category_created_at` (`created_at`),
  KEY `idx_cms_category_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文章分类';


DROP TABLE IF EXISTS `cms_homepage_feature`;

CREATE TABLE `cms_homepage_feature` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `module` varchar(20) NOT NULL COMMENT '模块标识: product/partner/team',
  `item_id` bigint unsigned NOT NULL COMMENT '业务条目ID(crm_product.id / crm_customer.id / sys_user.id)',
  `sort` int NOT NULL DEFAULT '0' COMMENT '展示排序(越小越靠前)',
  `created_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_module_item` (`module`,`item_id`),
  KEY `idx_module_sort` (`module`,`sort`),
  KEY `idx_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='CMS首页精选条目';


DROP TABLE IF EXISTS `cms_homepage_module`;

CREATE TABLE `cms_homepage_module` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `module` varchar(20) NOT NULL COMMENT '模块标识: product/partner/team',
  `module_name` varchar(50) NOT NULL DEFAULT '' COMMENT '模块中文名',
  `enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否在CMS首页显示',
  `sort` int NOT NULL DEFAULT '0' COMMENT '板块排序(越小越靠前)',
  `created_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_module` (`module`),
  KEY `idx_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='CMS首页板块开关';


DROP TABLE IF EXISTS `cms_page`;

CREATE TABLE `cms_page` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `slug` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL别名',
  `link_type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT 'page' COMMENT 'page内部页/link外部链接',
  `external_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外部链接URL',
  `content` longtext COLLATE utf8mb4_unicode_ci COMMENT '正文',
  `status` tinyint DEFAULT '1' COMMENT '1启用 0禁用',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_cms_page_slug` (`slug`),
  KEY `idx_cms_page_created_at` (`created_at`),
  KEY `idx_cms_page_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='单页';


DROP TABLE IF EXISTS `cms_push_log`;

CREATE TABLE `cms_push_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `channel` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '通道 baidu/indexnow',
  `url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '推送URL',
  `ref_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '关联类型 cms_article/custom',
  `ref_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '关联ID(0=纯URL)',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'success/failed/skipped',
  `http_code` int NOT NULL DEFAULT '0' COMMENT 'HTTP状态码(0=未发出请求)',
  `resp_body` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '响应摘要(截断)',
  `error` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '失败或跳过原因',
  `batch_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '批次ID(同一次推送操作共享)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_channel_url_created` (`channel`,`url`,`created_at`),
  KEY `idx_batch_id` (`batch_id`),
  KEY `idx_cms_push_log_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=75 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='搜索引擎推送日志';


DROP TABLE IF EXISTS `cms_tag`;

CREATE TABLE `cms_tag` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标签名称',
  `slug` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL别名',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `status` tinyint DEFAULT '1' COMMENT '1启用 0禁用',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_cms_tag_slug` (`slug`),
  KEY `idx_cms_tag_created_at` (`created_at`),
  KEY `idx_cms_tag_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='标签';


DROP TABLE IF EXISTS `cms_track_event`;

CREATE TABLE `cms_track_event` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `event` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '事件名',
  `path` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '页面路径',
  `title` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '页面标题',
  `referrer` varchar(500) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '来源页',
  `visitor_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '匿名访客ID',
  `session_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '会话ID',
  `props` json DEFAULT NULL COMMENT '扩展属性JSON',
  `ip` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '上报IP',
  `ua` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT 'User-Agent',
  `created_at` datetime(3) DEFAULT NULL COMMENT '上报时间',
  PRIMARY KEY (`id`),
  KEY `idx_cms_track_event_event` (`event`),
  KEY `idx_cms_track_event_path` (`path`),
  KEY `idx_cms_track_event_visitor` (`visitor_id`),
  KEY `idx_cms_track_event_ip` (`ip`),
  KEY `idx_cms_track_event_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3378 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='CMS官网埋点事件';
































DROP TABLE IF EXISTS `console_accounts`;

CREATE TABLE `console_accounts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `username` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '登录名',
  `password_hash` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'bcrypt 密码哈希',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态:1启用 0禁用',
  `token_version` int NOT NULL DEFAULT '0' COMMENT '会话版本(改密+1,旧令牌立即失效)',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_console_username` (`username`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='运营控制台账号(独立账号体系)';


DROP TABLE IF EXISTS `contract_field`;

CREATE TABLE `contract_field` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '合同ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段定义ID(关联sys_module_field)',
  `field_value` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值',
  PRIMARY KEY (`id`),
  KEY `idx_c_rfv` (`resource_id`,`field_id`,`field_value`),
  KEY `idx_contract_field_field_id` (`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='合同自定义字段值';

DROP TABLE IF EXISTS `contract_field_blob`;

CREATE TABLE `contract_field_blob` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `tenant_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '租户ID(0=平台数据)',
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '合同ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段定义ID(关联sys_module_field)',
  `field_value` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值(大文本)',
  PRIMARY KEY (`id`),
  KEY `idx_contract_field_blob_resource_id` (`resource_id`),
  KEY `idx_contract_field_blob_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='合同自定义字段大值';

DROP TABLE IF EXISTS `crm_business_title`;

CREATE TABLE `crm_business_title` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '企业名称',
  `tax_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '税号',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地址',
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `bank_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '开户行',
  `bank_account` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '银行账号',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_business_title_name` (`name`),
  KEY `idx_crm_business_title_created_at` (`created_at`),
  KEY `idx_crm_business_title_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工商抬头(开票用的企业信息)';

DROP TABLE IF EXISTS `crm_contract`;

CREATE TABLE `crm_contract` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `contract_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同编号',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '合同名称',
  `customer_id` bigint unsigned NOT NULL COMMENT '客户ID',
  `opportunity_id` bigint unsigned DEFAULT NULL COMMENT '来源商机ID',
  `title_id` bigint unsigned DEFAULT NULL COMMENT '工商抬头ID',
  `total_amount` decimal(14,2) NOT NULL COMMENT '合同总额',
  `received_amount` decimal(14,2) DEFAULT '0.00' COMMENT '已回款总额(累计维护)',
  `signed_date` date DEFAULT NULL COMMENT '签订日期',
  `start_date` date DEFAULT NULL COMMENT '开始日期',
  `end_date` date DEFAULT NULL COMMENT '结束日期',
  `stage` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT '阶段(字典CONTRACT_STAGE)',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '负责人',
  `follower_id` bigint unsigned DEFAULT NULL COMMENT '最新跟进人',
  `follow_time` datetime(3) DEFAULT NULL COMMENT '最新跟进时间',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '合同内容/备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  `approval_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'NONE' COMMENT '审批状态(NONE/PROCESSING/APPROVED/REJECTED/REVOKED)',
  PRIMARY KEY (`id`),
  KEY `idx_contract_customer` (`customer_id`),
  KEY `idx_crm_contract_opportunity_id` (`opportunity_id`),
  KEY `idx_crm_contract_stage` (`stage`),
  KEY `idx_contract_owner` (`owner_id`),
  KEY `idx_crm_contract_created_at` (`created_at`),
  KEY `idx_crm_contract_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=90 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 合同';


DROP TABLE IF EXISTS `crm_contract_item`;

CREATE TABLE `crm_contract_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `contract_id` bigint unsigned NOT NULL COMMENT '合同ID',
  `product_id` bigint unsigned DEFAULT NULL COMMENT '关联产品ID',
  `product_name` varchar(255) NOT NULL COMMENT '产品名称',
  `quantity` decimal(14,2) NOT NULL DEFAULT '1.00' COMMENT '数量',
  `unit` varchar(20) DEFAULT NULL COMMENT '单位',
  `unit_price` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '单价',
  `amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '小计(数量*单价)',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_contract_item_contract` (`contract_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='合同产品明细';


DROP TABLE IF EXISTS `crm_contract_payment_plan`;

CREATE TABLE `crm_contract_payment_plan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `contract_id` bigint unsigned NOT NULL COMMENT '合同ID',
  `plan_date` date NOT NULL COMMENT '计划回款日期',
  `plan_amount` decimal(14,2) NOT NULL COMMENT '计划金额',
  `received_amount` decimal(14,2) DEFAULT '0.00' COMMENT '已回款金额(累计维护)',
  `status` tinyint DEFAULT '0' COMMENT '0未回款 1部分 2已回款',
  `remark` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_contract_payment_plan_contract_id` (`contract_id`),
  KEY `idx_crm_contract_payment_plan_created_at` (`created_at`),
  KEY `idx_crm_contract_payment_plan_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=63 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='回款计划';


DROP TABLE IF EXISTS `crm_contract_payment_record`;

CREATE TABLE `crm_contract_payment_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `contract_id` bigint unsigned NOT NULL COMMENT '合同ID',
  `plan_id` bigint unsigned DEFAULT NULL COMMENT '关联回款计划(可选)',
  `received_date` date NOT NULL COMMENT '实际回款日期',
  `amount` decimal(14,2) NOT NULL COMMENT '回款金额',
  `method` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '回款方式(字典PAYMENT_METHOD)',
  `remark` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_contract_payment_record_contract_id` (`contract_id`),
  KEY `idx_crm_contract_payment_record_plan_id` (`plan_id`),
  KEY `idx_crm_contract_payment_record_created_at` (`created_at`),
  KEY `idx_crm_contract_payment_record_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=98 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='回款记录';


DROP TABLE IF EXISTS `crm_contract_template`;

CREATE TABLE `crm_contract_template` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) NOT NULL COMMENT '模板名称',
  `content` longtext NOT NULL COMMENT 'Markdown正文(含${变量}占位符)',
  `remark` varchar(500) DEFAULT NULL COMMENT '说明',
  `enabled` tinyint NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '创建人',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_ct_enabled` (`enabled`,`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='合同模板';


DROP TABLE IF EXISTS `crm_customer`;

CREATE TABLE `crm_customer` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户名称',
  `customer_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户编号',
  `level` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户级别(字典CUSTOMER_LEVEL)',
  `source` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户来源(字典CUSTOMER_SOURCE)',
  `status` tinyint DEFAULT '1' COMMENT '1正常 2冻结 3流失',
  `industry` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行业(字典INDUSTRY)',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '负责人ID(公海时NULL)',
  `follower_id` bigint unsigned DEFAULT NULL COMMENT '最新跟进人ID',
  `follow_time` datetime DEFAULT NULL COMMENT '最新跟进时间',
  `in_pool` tinyint DEFAULT '0' COMMENT '0私海 1公海',
  `pool_id` bigint unsigned DEFAULT NULL COMMENT '公海ID',
  `collection_time` datetime(3) DEFAULT NULL COMMENT '领取时间',
  `pool_reason` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '进公海原因',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_customer_level` (`level`),
  KEY `idx_crm_customer_industry` (`industry`),
  KEY `idx_owner` (`owner_id`),
  KEY `idx_pool` (`in_pool`,`pool_id`),
  KEY `idx_crm_customer_created_at` (`created_at`),
  KEY `idx_crm_customer_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=230 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 客户';


DROP TABLE IF EXISTS `crm_customer_contact`;

CREATE TABLE `crm_customer_contact` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `customer_id` bigint unsigned NOT NULL COMMENT '客户ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系人姓名',
  `contact_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人编号',
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `position` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职务',
  `department` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '部门',
  `is_key_decision_maker` tinyint DEFAULT '0' COMMENT '0否 1是关键决策人',
  `status` tinyint DEFAULT '1' COMMENT '1正常 2停用',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_customer` (`customer_id`),
  KEY `idx_crm_customer_contact_created_at` (`created_at`),
  KEY `idx_crm_customer_contact_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=87 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='客户联系人';


DROP TABLE IF EXISTS `crm_customer_owner_history`;

CREATE TABLE `crm_customer_owner_history` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `customer_id` bigint unsigned NOT NULL COMMENT '客户ID',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '当时的负责人(进公海时NULL)',
  `action` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'TAKE/RELEASE/TRANSFER/RECYCLE',
  `operator_id` bigint unsigned NOT NULL COMMENT '操作人',
  `reason` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原因',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_customer_owner_history_customer_id` (`customer_id`),
  KEY `idx_crm_customer_owner_history_owner_id` (`owner_id`),
  KEY `idx_crm_customer_owner_history_action` (`action`),
  KEY `idx_crm_customer_owner_history_created_at` (`created_at`),
  KEY `idx_crm_customer_owner_history_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=156 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='客户归属变更历史(追加写,不软删除)';


DROP TABLE IF EXISTS `crm_customer_pool`;

CREATE TABLE `crm_customer_pool` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公海名称',
  `scope_dept_ids` text COLLATE utf8mb4_unicode_ci COMMENT '可见部门ID集合(JSON数组)',
  `scope_role_ids` text COLLATE utf8mb4_unicode_ci COMMENT '可见角色ID集合(JSON数组)',
  `admin_user_ids` text COLLATE utf8mb4_unicode_ci COMMENT '管理员用户ID集合(JSON数组)',
  `enabled` tinyint DEFAULT NULL COMMENT '1启用 0禁用',
  `auto_recycle` tinyint DEFAULT NULL COMMENT '1开启自动回收 0关闭',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  `is_default` tinyint DEFAULT '0' COMMENT '是否默认池(不可删)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_customer_pool_enabled` (`enabled`),
  KEY `idx_crm_customer_pool_created_at` (`created_at`),
  KEY `idx_crm_customer_pool_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公海池配置';


DROP TABLE IF EXISTS `crm_customer_pool_hidden_field`;

CREATE TABLE `crm_customer_pool_hidden_field` (
  `pool_id` bigint unsigned NOT NULL COMMENT '公海池ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '自定义字段ID',
  PRIMARY KEY (`pool_id`,`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公海隐藏字段(复合主键 pool_id + field_id)';

DROP TABLE IF EXISTS `crm_customer_pool_pick_rule`;

CREATE TABLE `crm_customer_pool_pick_rule` (
  `pool_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '公海池ID(主键,1:1)',
  `limit_daily` tinyint DEFAULT '0' COMMENT '1限制每日领取数',
  `daily_limit` bigint DEFAULT '0' COMMENT '每日领取上限',
  `limit_prev_owner` tinyint DEFAULT '0' COMMENT '1限制前归属人领取',
  `prev_owner_interval` bigint DEFAULT '0' COMMENT '前归属人重新领取间隔天数',
  `limit_new_data` tinyint DEFAULT '0' COMMENT '1限制新数据冷却期',
  `new_data_interval` bigint DEFAULT '0' COMMENT '新数据冷却天数',
  PRIMARY KEY (`pool_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='领取规则(1:1 with pool,pool_id 主键)';

DROP TABLE IF EXISTS `crm_customer_pool_recycle_rule`;

CREATE TABLE `crm_customer_pool_recycle_rule` (
  `pool_id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '公海池ID(主键,1:1)',
  `operator` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT 'AND' COMMENT '多条件组合 AND/OR',
  `conditions` text COLLATE utf8mb4_unicode_ci COMMENT '回收条件JSON数组',
  PRIMARY KEY (`pool_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='回收规则(1:1 with pool)';


DROP TABLE IF EXISTS `crm_lead`;

CREATE TABLE `crm_lead` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '线索名称',
  `lead_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '线索编号',
  `contact_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人姓名',
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `company` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司',
  `level` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '线索级别(字典LEAD_LEVEL)',
  `source` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '线索来源(字典LEAD_SOURCE)',
  `status` tinyint DEFAULT '1' COMMENT '1新建 2跟进中 3已转化 4无效',
  `industry` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '行业(字典INDUSTRY)',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '负责人ID(公海时NULL)',
  `follower_id` bigint unsigned DEFAULT NULL COMMENT '最新跟进人ID',
  `follow_time` datetime DEFAULT NULL COMMENT '最新跟进时间',
  `in_pool` tinyint DEFAULT '0' COMMENT '0私海 1公海',
  `pool_id` bigint unsigned DEFAULT NULL COMMENT '线索公海ID',
  `collection_time` datetime DEFAULT NULL COMMENT '领取时间',
  `pool_reason` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '进公海原因',
  `converted_customer_id` bigint unsigned DEFAULT NULL COMMENT '转化后的客户ID',
  `converted_at` datetime DEFAULT NULL COMMENT '转化时间',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  `remark` text COLLATE utf8mb4_unicode_ci COMMENT '留言内容(官网表单)',
  PRIMARY KEY (`id`),
  KEY `idx_lead_lead_level` (`level`),
  KEY `idx_lead_industry` (`industry`),
  KEY `idx_lead_owner` (`owner_id`),
  KEY `idx_lead_pool` (`in_pool`,`pool_id`),
  KEY `idx_lead_converted_customer_id` (`converted_customer_id`),
  KEY `idx_crm_lead_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=606 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 线索';


DROP TABLE IF EXISTS `crm_lead_owner_history`;

CREATE TABLE `crm_lead_owner_history` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `lead_id` bigint unsigned NOT NULL COMMENT '线索ID',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '当时的负责人(进公海时NULL)',
  `action` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'TAKE/RELEASE/TRANSFER/RECYCLE',
  `operator_id` bigint unsigned NOT NULL COMMENT '操作人',
  `reason` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原因',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_lead_owner_history_lead_id` (`lead_id`),
  KEY `idx_crm_lead_owner_history_owner_id` (`owner_id`),
  KEY `idx_crm_lead_owner_history_action` (`action`),
  KEY `idx_crm_lead_owner_history_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=614 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 线索归属历史';


DROP TABLE IF EXISTS `crm_lead_pool`;

CREATE TABLE `crm_lead_pool` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公海名称',
  `scope_dept_ids` text COLLATE utf8mb4_unicode_ci COMMENT '可见部门ID集合(JSON数组)',
  `scope_role_ids` text COLLATE utf8mb4_unicode_ci COMMENT '可见角色ID集合(JSON数组)',
  `admin_user_ids` text COLLATE utf8mb4_unicode_ci COMMENT '管理员用户ID集合(JSON数组)',
  `enabled` tinyint DEFAULT NULL COMMENT '1启用 0禁用',
  `auto_recycle` tinyint DEFAULT NULL COMMENT '1开启自动回收 0关闭',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  `is_default` tinyint DEFAULT '0' COMMENT '是否默认池(不可删)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_lead_pool_enabled` (`enabled`),
  KEY `idx_crm_lead_pool_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 线索公海池';


DROP TABLE IF EXISTS `crm_lead_pool_pick_rule`;

CREATE TABLE `crm_lead_pool_pick_rule` (
  `pool_id` bigint unsigned NOT NULL COMMENT '线索公海池ID(主键,1:1)',
  `limit_daily` tinyint DEFAULT '0' COMMENT '1限制每日领取数',
  `daily_limit` bigint DEFAULT '0' COMMENT '每日领取上限',
  `limit_prev_owner` tinyint DEFAULT '0' COMMENT '1限制前归属人领取',
  `prev_owner_interval` bigint DEFAULT '0' COMMENT '前归属人重新领取间隔天数',
  `limit_new_data` tinyint DEFAULT '0' COMMENT '1限制新数据冷却期',
  `new_data_interval` bigint DEFAULT '0' COMMENT '新数据冷却天数',
  PRIMARY KEY (`pool_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 线索领取规则';

DROP TABLE IF EXISTS `crm_lead_pool_recycle_rule`;

CREATE TABLE `crm_lead_pool_recycle_rule` (
  `pool_id` bigint unsigned NOT NULL COMMENT '线索公海池ID(主键,1:1)',
  `operator` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT 'AND' COMMENT '多条件组合 AND/OR',
  `conditions` text COLLATE utf8mb4_unicode_ci COMMENT '回收条件JSON数组',
  PRIMARY KEY (`pool_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 线索回收规则';


DROP TABLE IF EXISTS `crm_opportunity`;

CREATE TABLE `crm_opportunity` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商机名称',
  `opportunity_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商机编号',
  `customer_id` bigint unsigned NOT NULL COMMENT '关联客户ID',
  `expected_amount` decimal(14,2) DEFAULT NULL COMMENT '预计金额',
  `expected_close_date` date DEFAULT NULL COMMENT '预计成交日期',
  `stage` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PROSPECTING' COMMENT '阶段(字典OPPORTUNITY_STAGE)',
  `probability` bigint DEFAULT NULL COMMENT '成交概率0-100',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '负责人',
  `follower_id` bigint unsigned DEFAULT NULL COMMENT '最新跟进人',
  `follow_time` datetime(3) DEFAULT NULL COMMENT '最新跟进时间',
  `source_clue_id` bigint unsigned DEFAULT NULL COMMENT '来源线索ID',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_opp_customer` (`customer_id`),
  KEY `idx_opp_stage` (`stage`),
  KEY `idx_opp_owner` (`owner_id`),
  KEY `idx_crm_opportunity_created_at` (`created_at`),
  KEY `idx_crm_opportunity_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=89 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 商机';


DROP TABLE IF EXISTS `crm_product`;

CREATE TABLE `crm_product` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '产品名称',
  `product_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品编号',
  `category` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类(字典PRODUCT_CATEGORY)',
  `unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `standard_price` decimal(14,2) DEFAULT NULL COMMENT '标准价格',
  `cost_price` decimal(14,2) DEFAULT NULL COMMENT '成本价',
  `status` tinyint DEFAULT '1' COMMENT '1上架 2下架',
  `image_url` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品主图URL',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_product_name` (`name`),
  KEY `idx_crm_product_category` (`category`),
  KEY `idx_crm_product_status` (`status`),
  KEY `idx_crm_product_created_at` (`created_at`),
  KEY `idx_crm_product_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=182 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='CRM 商品';



DROP TABLE IF EXISTS `crm_product_sku`;

CREATE TABLE `crm_product_sku` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL COMMENT '商品ID(引用crm_product.id)',
  `spec` varchar(128) NOT NULL DEFAULT '' COMMENT '规格描述(空=默认规格)',
  `sku_no` varchar(64) DEFAULT NULL COMMENT 'SKU编号',
  `price` decimal(14,2) DEFAULT NULL COMMENT '售价',
  `cost_price` decimal(14,2) DEFAULT NULL COMMENT '成本价',
  `image_url` varchar(512) DEFAULT NULL COMMENT '规格图URL',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sku_no` (`sku_no`),
  KEY `idx_product` (`product_id`),
  KEY `idx_crm_product_sku_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品规格SKU';


DROP TABLE IF EXISTS `crm_ticket`;

CREATE TABLE `crm_ticket` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `ticket_no` varchar(64) NOT NULL COMMENT '工单编号',
  `title` varchar(200) NOT NULL COMMENT '标题',
  `description` varchar(2000) DEFAULT '' COMMENT '问题描述',
  `customer_id` bigint unsigned DEFAULT NULL COMMENT '客户ID',
  `customer_name` varchar(200) DEFAULT '' COMMENT '客户名称',
  `contract_id` bigint unsigned DEFAULT NULL COMMENT '关联合同ID',
  `contact_name` varchar(100) DEFAULT '' COMMENT '联系人',
  `contact_phone` varchar(50) DEFAULT '' COMMENT '联系电话',
  `category` varchar(32) DEFAULT '' COMMENT '问题类型',
  `priority` tinyint NOT NULL DEFAULT '2' COMMENT '1低2中3高4紧急',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1待处理2处理中3已解决4已关闭5已重开',
  `handler_id` bigint unsigned DEFAULT NULL COMMENT '处理人ID',
  `solution` varchar(2000) DEFAULT '' COMMENT '解决方案',
  `resolved_at` datetime DEFAULT NULL COMMENT '解决时间',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_crm_ticket_no` (`ticket_no`),
  KEY `idx_crm_ticket_customer` (`customer_id`),
  KEY `idx_crm_ticket_contract` (`contract_id`),
  KEY `idx_crm_ticket_status` (`status`),
  KEY `idx_crm_ticket_handler` (`handler_id`),
  KEY `idx_crm_ticket_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='CRM 售后工单';


DROP TABLE IF EXISTS `crm_ticket_log`;

CREATE TABLE `crm_ticket_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `ticket_id` bigint unsigned NOT NULL COMMENT '工单ID',
  `content` varchar(2000) NOT NULL COMMENT '处理内容',
  `operator_id` bigint unsigned DEFAULT NULL COMMENT '操作人ID',
  `old_status` tinyint DEFAULT NULL COMMENT '变更前状态',
  `new_status` tinyint DEFAULT NULL COMMENT '变更后状态',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_crm_ticketlog_ticket` (`ticket_id`),
  KEY `idx_crm_ticketlog_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='CRM 工单处理日志';


DROP TABLE IF EXISTS `customer_field`;

CREATE TABLE `customer_field` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段ID',
  `field_value` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值',
  PRIMARY KEY (`id`),
  KEY `idx_rfv` (`resource_id`,`field_id`,`field_value`),
  KEY `idx_customer_field_field_id` (`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='客户自定义字段值(单值)';


DROP TABLE IF EXISTS `customer_field_blob`;

CREATE TABLE `customer_field_blob` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `tenant_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '租户ID(0=平台数据)',
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '客户ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段定义ID(关联sys_module_field)',
  `field_value` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值(大文本)',
  PRIMARY KEY (`id`),
  KEY `idx_customer_field_blob_resource_id` (`resource_id`),
  KEY `idx_customer_field_blob_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='客户自定义字段大值';


DROP TABLE IF EXISTS `fin_account`;

CREATE TABLE `fin_account` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '科目编码(如1001)',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '科目名称',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ASSET/LIABILITY/EQUITY/INCOME/EXPENSE',
  `parent_id` bigint unsigned DEFAULT NULL COMMENT '上级科目ID',
  `balance_dir` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'DEBIT/CREDIT',
  `level` bigint DEFAULT '1' COMMENT '层级',
  `is_leaf` tinyint(1) DEFAULT '1' COMMENT '是否末级科目(凭证只能选末级)',
  `status` tinyint DEFAULT '1' COMMENT '1启用0禁用',
  `sort` bigint DEFAULT '0' COMMENT '排序号',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_fin_account_code` (`code`),
  KEY `idx_fin_account_type` (`type`),
  KEY `idx_fin_account_parent_id` (`parent_id`),
  KEY `idx_fin_account_created_at` (`created_at`),
  KEY `idx_fin_account_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='会计科目';


DROP TABLE IF EXISTS `fin_invoice`;

CREATE TABLE `fin_invoice` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `invoice_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发票号码',
  `invoice_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发票类型(VAT_SPECIAL增值税专票/VAT_NORMAL普票/ELECTRONIC电子发票)',
  `direction` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'RECEIVED收票/ISSUED开票',
  `invoice_date` date NOT NULL COMMENT '开票日期',
  `amount` decimal(14,2) NOT NULL COMMENT '不含税金额',
  `tax_rate` decimal(5,4) DEFAULT NULL COMMENT '税率(如0.13)',
  `tax_amount` decimal(14,2) DEFAULT NULL COMMENT '税额',
  `total_amount` decimal(14,2) NOT NULL COMMENT '价税合计',
  `party_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '对方名称(客户/供应商)',
  `party_tax_no` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '对方税号',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CONTRACT/PURCHASE/SALES',
  `biz_id` bigint unsigned DEFAULT NULL COMMENT '业务单据ID',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_fin_invoice_invoice_no` (`invoice_no`),
  KEY `idx_fin_invoice_direction` (`direction`),
  KEY `idx_fin_invoice_invoice_date` (`invoice_date`),
  KEY `idx_fin_invoice_created_at` (`created_at`),
  KEY `idx_fin_invoice_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='发票管理';


DROP TABLE IF EXISTS `fin_receivable`;

CREATE TABLE `fin_receivable` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `doc_no` varchar(64) NOT NULL COMMENT '往来单号',
  `direction` varchar(20) NOT NULL COMMENT 'RECEIVABLE应收/PAYABLE应付',
  `party_type` varchar(20) DEFAULT '' COMMENT 'CUSTOMER/SUPPLIER/EMPLOYEE',
  `party_id` bigint unsigned DEFAULT NULL COMMENT '往来方ID',
  `party_name` varchar(200) DEFAULT '' COMMENT '往来方名称',
  `occur_date` date NOT NULL COMMENT '发生日期',
  `due_date` date DEFAULT NULL COMMENT '到期日期',
  `original_amount` decimal(14,2) NOT NULL COMMENT '原始金额',
  `settled_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '已结算金额',
  `biz_type` varchar(32) DEFAULT '' COMMENT 'CONTRACT/PURCHASE_ORDER/LOAN等',
  `biz_id` bigint unsigned DEFAULT NULL COMMENT '业务单据ID',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0未结算1部分2已结清',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_fin_recv_doc` (`doc_no`),
  KEY `idx_fin_recv_direction` (`direction`),
  KEY `idx_fin_recv_party` (`party_id`),
  KEY `idx_fin_recv_status` (`status`),
  KEY `idx_fin_recv_biz` (`biz_id`),
  KEY `idx_fin_recv_occur` (`occur_date`),
  KEY `idx_fin_recv_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='应收应付往来台账';


DROP TABLE IF EXISTS `fin_voucher`;

CREATE TABLE `fin_voucher` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `voucher_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '凭证编号',
  `voucher_date` date NOT NULL COMMENT '凭证日期',
  `account_id` bigint unsigned NOT NULL COMMENT '科目ID',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '摘要',
  `direction` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'DEBIT借/CREDIT贷',
  `amount` decimal(14,2) NOT NULL COMMENT '金额',
  `currency` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT 'CNY' COMMENT '币种',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '业务类型(CONTRACT_PAYMENT/PURCHASE/SALES等)',
  `biz_id` bigint unsigned DEFAULT NULL COMMENT '业务单据ID',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'DRAFT' COMMENT 'DRAFT/CONFIRMED',
  `operator_id` bigint unsigned DEFAULT NULL COMMENT '制单人ID',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_fin_voucher_voucher_no` (`voucher_no`),
  KEY `idx_fin_voucher_voucher_date` (`voucher_date`),
  KEY `idx_fin_voucher_account_id` (`account_id`),
  KEY `idx_fin_voucher_status` (`status`),
  KEY `idx_fin_voucher_created_at` (`created_at`),
  KEY `idx_fin_voucher_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=106 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='记账凭证';


DROP TABLE IF EXISTS `follow_up_plan`;

CREATE TABLE `follow_up_plan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '计划类型',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '计划内容',
  `plan_time` datetime(3) NOT NULL COMMENT '计划跟进时间',
  `remind_time` datetime(3) DEFAULT NULL COMMENT '提醒时间(早于plan_time)',
  `owner_id` bigint unsigned NOT NULL COMMENT '负责人',
  `lead_id` bigint unsigned DEFAULT NULL COMMENT '关联线索',
  `customer_id` bigint unsigned DEFAULT NULL COMMENT '关联客户',
  `opportunity_id` bigint unsigned DEFAULT NULL COMMENT '关联商机',
  `contact_id` bigint unsigned DEFAULT NULL COMMENT '关联联系人',
  `contract_id` bigint unsigned DEFAULT NULL COMMENT '关联合同',
  `status` tinyint DEFAULT '0' COMMENT '0待办 1已转记录 2已跳过',
  `reminded` tinyint DEFAULT '0' COMMENT '是否已发提醒',
  `record_id` bigint unsigned DEFAULT NULL COMMENT '转入的记录ID',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_follow_up_plan_owner_id` (`owner_id`),
  KEY `idx_follow_up_plan_customer_id` (`customer_id`),
  KEY `idx_follow_up_plan_opportunity_id` (`opportunity_id`),
  KEY `idx_follow_up_plan_contact_id` (`contact_id`),
  KEY `idx_follow_up_plan_contract_id` (`contract_id`),
  KEY `idx_follow_up_plan_created_at` (`created_at`),
  KEY `idx_follow_up_plan_deleted_at` (`deleted_at`),
  KEY `idx_follow_plan_lead` (`lead_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟进计划/待办';


DROP TABLE IF EXISTS `follow_up_record`;

CREATE TABLE `follow_up_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `follow_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '跟进编号',
  `type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '跟进类型(WECHAT/PHONE/VISIT/EMAIL/OTHER)',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '跟进内容',
  `follow_time` datetime(3) NOT NULL COMMENT '跟进发生时间',
  `owner_id` bigint unsigned NOT NULL COMMENT '负责人',
  `lead_id` bigint unsigned DEFAULT NULL COMMENT '关联线索',
  `customer_id` bigint unsigned DEFAULT NULL COMMENT '关联客户',
  `opportunity_id` bigint unsigned DEFAULT NULL COMMENT '关联商机',
  `contact_id` bigint unsigned DEFAULT NULL COMMENT '关联联系人',
  `contract_id` bigint unsigned DEFAULT NULL COMMENT '关联合同',
  `plan_id` bigint unsigned DEFAULT NULL COMMENT '来源计划(计划转记录时填)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_follow_up_record_owner_id` (`owner_id`),
  KEY `idx_follow_up_record_customer_id` (`customer_id`),
  KEY `idx_follow_up_record_opportunity_id` (`opportunity_id`),
  KEY `idx_follow_up_record_contact_id` (`contact_id`),
  KEY `idx_follow_up_record_contract_id` (`contract_id`),
  KEY `idx_follow_up_record_plan_id` (`plan_id`),
  KEY `idx_follow_up_record_created_at` (`created_at`),
  KEY `idx_follow_up_record_deleted_at` (`deleted_at`),
  KEY `idx_follow_record_lead` (`lead_id`)
) ENGINE=InnoDB AUTO_INCREMENT=138 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟进记录';


DROP TABLE IF EXISTS `follow_up_record_field`;

CREATE TABLE `follow_up_record_field` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '跟进记录ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段定义ID(关联sys_module_field)',
  `field_value` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值',
  PRIMARY KEY (`id`),
  KEY `idx_f_rfv` (`resource_id`,`field_id`,`field_value`),
  KEY `idx_follow_up_record_field_field_id` (`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟进记录自定义字段值';

DROP TABLE IF EXISTS `follow_up_record_field_blob`;

CREATE TABLE `follow_up_record_field_blob` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `tenant_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '租户ID(0=平台数据)',
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '跟进记录ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段定义ID(关联sys_module_field)',
  `field_value` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值(大文本)',
  PRIMARY KEY (`id`),
  KEY `idx_follow_up_record_field_blob_resource_id` (`resource_id`),
  KEY `idx_follow_up_record_field_blob_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟进记录自定义字段大值';

DROP TABLE IF EXISTS `geo_platform`;

CREATE TABLE `geo_platform` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台名',
  `base_url` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'OpenAI兼容API根地址',
  `api_key` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '平台APIKey(接口不回显)',
  `model` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型名',
  `enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否参与监测',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GEO 监测平台';


DROP TABLE IF EXISTS `geo_platform_account`;

CREATE TABLE `geo_platform_account` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `platform` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'douyin/...',
  `open_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台用户openid',
  `nickname` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '账号昵称',
  `access_token` varchar(1024) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '访问令牌(接口不回显)',
  `refresh_token` varchar(1024) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '刷新令牌(接口不回显)',
  `expires_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'access_token过期时间',
  `scope` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '授权scope',
  `enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否可用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_platform_openid` (`platform`,`open_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GEO 信源平台授权账号';

DROP TABLE IF EXISTS `geo_prompt`;

CREATE TABLE `geo_prompt` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `question` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '完整监测问题',
  `group_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'category' COMMENT 'brand/category/scenario',
  `enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否参与监测',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序值',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_group_sort` (`group_type`,`sort`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GEO 监测提示词库';


DROP TABLE IF EXISTS `geo_result`;

CREATE TABLE `geo_result` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `run_id` bigint unsigned NOT NULL COMMENT '轮次ID',
  `prompt_id` bigint unsigned NOT NULL COMMENT '提示词ID',
  `platform_id` bigint unsigned NOT NULL COMMENT '平台ID',
  `score` int NOT NULL DEFAULT '0' COMMENT '0未提及/1提及行简/2提及且带官网链接',
  `mention_brand` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否提及行简',
  `has_own_link` tinyint(1) NOT NULL DEFAULT '0' COMMENT '回答是否含官网链接',
  `own_cite` tinyint(1) NOT NULL DEFAULT '0' COMMENT '引用是否命中自有域名',
  `cited_urls` text COLLATE utf8mb4_unicode_ci COMMENT '引用URL(JSON数组)',
  `competitors` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '命中的竞品名(逗号分隔)',
  `latency_ms` int NOT NULL DEFAULT '0' COMMENT '调用耗时(毫秒)',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ok' COMMENT 'ok/error',
  `error_msg` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '失败原因摘要',
  `answer` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '回答全文(监测证据)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_run_platform_score` (`run_id`,`platform_id`,`score`)
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GEO 监测结果';



DROP TABLE IF EXISTS `geo_run`;

CREATE TABLE `geo_run` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `trigger` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual' COMMENT 'manual/schedule',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'running' COMMENT 'running/done/failed',
  `total_results` int NOT NULL DEFAULT '0' COMMENT '结果条数(含失败)',
  `error_count` int NOT NULL DEFAULT '0' COMMENT '失败条数',
  `mentioned_count` int NOT NULL DEFAULT '0' COMMENT '提及行简条数',
  `with_link_count` int NOT NULL DEFAULT '0' COMMENT '提及且带官网链接条数',
  `total_score` int NOT NULL DEFAULT '0' COMMENT '得分合计',
  `max_score` int NOT NULL DEFAULT '0' COMMENT '满分(提示词×平台×2)',
  `recommend_rate` double NOT NULL DEFAULT '0' COMMENT 'AI推荐率(0-1)',
  `own_cite_rate` double NOT NULL DEFAULT '0' COMMENT '自有引用命中率(0-1)',
  `error_msg` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '失败原因摘要',
  `started_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '开始时间',
  `finished_at` datetime DEFAULT NULL COMMENT '完成时间',
  PRIMARY KEY (`id`),
  KEY `idx_status_started` (`status`,`started_at`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GEO 监测轮次';


DROP TABLE IF EXISTS `geo_source`;

CREATE TABLE `geo_source` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `topic_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '选题ID(0=手工稿)',
  `content_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'article' COMMENT 'article/video/video_script',
  `platform` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'wechat_mp' COMMENT 'wechat_mp/douyin/xhs/zhihu/csdn/toutiao',
  `genre` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '体裁 comparison/faq/case',
  `title` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '标题',
  `digest` varchar(256) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '摘要(公众号120字节内)',
  `content_md` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '正文Markdown(视频稿为口播脚本+分镜描述)',
  `video_url` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '视频文件地址(OSS/CDN)',
  `video_task_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '视频生成任务号',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'generated' COMMENT 'generated/pushed/published/failed/skipped',
  `media_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '公众号草稿media_id',
  `publish_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'freepublish发布任务ID',
  `publish_url` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '发布URL(接口拉取或人工回填)',
  `variant_of` bigint unsigned NOT NULL DEFAULT '0' COMMENT '母稿ID(0=母稿)',
  `trigger` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual' COMMENT 'manual/schedule',
  `error` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '失败原因摘要',
  `qc_status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none' COMMENT 'AI质检状态(none/pass/warn/blocked)',
  `qc_result` json DEFAULT NULL COMMENT 'AI质检结果JSON(分维度得分/原文定位/修改建议/checked_at/model)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_topic` (`topic_id`),
  KEY `idx_status` (`status`),
  KEY `idx_platform_type` (`platform`,`content_type`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GEO 信源稿件库';


DROP TABLE IF EXISTS `geo_topic`;

CREATE TABLE `geo_topic` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `question` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '选题问题(完整问句)',
  `origin` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ai' COMMENT '来源 matrix=手册矩阵/ai=AI生成/manual=手工',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'pending/approved/rejected/used',
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '选题依据(监测低分/竞品提及/引用缺口)',
  `source_run_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '来源监测轮次ID(0=无关)',
  `prompt_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '关联既有提示词ID(0=新题)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_status_origin` (`status`,`origin`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='GEO 信源选题池';


DROP TABLE IF EXISTS `hrm_attendance_clock`;

CREATE TABLE `hrm_attendance_clock` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `employee_id` bigint unsigned NOT NULL COMMENT '员工ID',
  `clock_date` date NOT NULL COMMENT '打卡日期',
  `clock_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'CHECK_IN/CHECK_OUT',
  `clock_time` datetime NOT NULL COMMENT '打卡时间',
  `location` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '打卡地点',
  `longitude` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '经度',
  `latitude` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纬度',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `source` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'APP' COMMENT '打卡来源(APP/WECOM)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_clock_emp_date` (`employee_id`,`clock_date`),
  KEY `idx_hrm_attendance_clock_created_at` (`created_at`),
  KEY `idx_hrm_attendance_clock_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考勤打卡记录';


DROP TABLE IF EXISTS `hrm_attendance_group`;

CREATE TABLE `hrm_attendance_group` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '考勤组名称',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '绑定部门(NULL=不绑定仅手动指派)',
  `shift_id` bigint unsigned NOT NULL COMMENT '默认班次ID',
  `status` tinyint NOT NULL DEFAULT '1',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_dept` (`dept_id`),
  KEY `idx_shift` (`shift_id`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考勤组(按部门绑定默认班次)';

DROP TABLE IF EXISTS `hrm_attendance_summary`;

CREATE TABLE `hrm_attendance_summary` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `employee_id` bigint unsigned NOT NULL COMMENT '员工ID',
  `year_month` varchar(7) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '年月(2026-08)',
  `work_days` bigint DEFAULT '22' COMMENT '应出勤天数',
  `actual_days` bigint DEFAULT '0' COMMENT '实际出勤天数',
  `late_count` bigint DEFAULT '0' COMMENT '迟到次数',
  `early_count` bigint DEFAULT '0' COMMENT '早退次数',
  `missing_days` int NOT NULL DEFAULT '0' COMMENT '缺卡天数',
  `absent_days` decimal(5,1) DEFAULT '0.0' COMMENT '缺勤天数',
  `leave_days` decimal(5,1) DEFAULT '0.0' COMMENT '请假天数',
  `overtime_hours` decimal(5,1) DEFAULT '0.0' COMMENT '加班时长',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_att_summary` (`employee_id`,`year_month`),
  KEY `idx_hrm_attendance_summary_created_at` (`created_at`),
  KEY `idx_hrm_attendance_summary_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='月度考勤汇总(定时任务生成或手动统计)';


DROP TABLE IF EXISTS `hrm_candidate`;

CREATE TABLE `hrm_candidate` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `job_id` bigint unsigned NOT NULL COMMENT '职位ID',
  `name` varchar(100) NOT NULL COMMENT '姓名',
  `phone` varchar(50) DEFAULT '' COMMENT '电话',
  `email` varchar(100) DEFAULT '' COMMENT '邮箱',
  `gender` varchar(10) DEFAULT '' COMMENT '性别',
  `age` int DEFAULT '0' COMMENT '年龄',
  `education` varchar(32) DEFAULT '' COMMENT '学历',
  `experience` varchar(100) DEFAULT '' COMMENT '工作年限',
  `company` varchar(200) DEFAULT '' COMMENT '当前公司',
  `resume_url` varchar(500) DEFAULT '' COMMENT '简历链接',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1新简历2筛选3面试4offer5录用6淘汰',
  `source` varchar(100) DEFAULT '' COMMENT '来源',
  `interview_date` varchar(32) DEFAULT '' COMMENT '面试时间',
  `remark` varchar(1000) DEFAULT '' COMMENT '备注',
  `evaluator_id` bigint unsigned DEFAULT NULL COMMENT '评估人ID',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_hrm_cand_job` (`job_id`),
  KEY `idx_hrm_cand_status` (`status`),
  KEY `idx_hrm_cand_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='HRM 招聘候选人';


DROP TABLE IF EXISTS `hrm_department`;

CREATE TABLE `hrm_department` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `parent_id` bigint unsigned DEFAULT '0' COMMENT '父部门ID(0为根)',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部门名称',
  `code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '部门编码',
  `leader` bigint unsigned DEFAULT NULL COMMENT '负责人ID(关联sys_user)',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `status` tinyint DEFAULT '1' COMMENT '1正常 0禁用',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_hrm_department_code` (`code`),
  KEY `idx_hrm_department_parent_id` (`parent_id`),
  KEY `idx_hrm_department_created_at` (`created_at`),
  KEY `idx_hrm_department_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='部门';


DROP TABLE IF EXISTS `hrm_employee`;

CREATE TABLE `hrm_employee` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `emp_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '员工工号',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓名',
  `gender` tinyint DEFAULT '0' COMMENT '性别(0未知 1男 2女)',
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `email` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `department_id` bigint unsigned NOT NULL COMMENT '部门ID',
  `position_id` bigint unsigned NOT NULL COMMENT '岗位ID',
  `user_id` bigint unsigned DEFAULT NULL COMMENT '关联系统用户ID',
  `entry_date` date DEFAULT NULL COMMENT '入职日期',
  `resign_date` date DEFAULT NULL COMMENT '离职日期',
  `status` tinyint DEFAULT '1' COMMENT '1在职 2试用 3离职',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_hrm_employee_emp_no` (`emp_no`),
  KEY `idx_hrm_employee_department_id` (`department_id`),
  KEY `idx_hrm_employee_position_id` (`position_id`),
  KEY `idx_hrm_employee_user_id` (`user_id`),
  KEY `idx_hrm_employee_status` (`status`),
  KEY `idx_hrm_employee_created_at` (`created_at`),
  KEY `idx_hrm_employee_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='员工档案';


DROP TABLE IF EXISTS `hrm_holiday`;

CREATE TABLE `hrm_holiday` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `holiday_date` date NOT NULL COMMENT '日期',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称(如 国庆节/调休补班)',
  `type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'HOLIDAY放假 / WORKDAY调休补班',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_date` (`holiday_date`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='节假日(法定假日+调休补班)';

DROP TABLE IF EXISTS `hrm_insurance_plan`;

CREATE TABLE `hrm_insurance_plan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '方案名称',
  `pension_rate` decimal(6,4) NOT NULL DEFAULT '0.0000' COMMENT '养老比例(如 0.0800)',
  `medical_rate` decimal(6,4) NOT NULL DEFAULT '0.0000' COMMENT '医疗比例',
  `unemployment_rate` decimal(6,4) NOT NULL DEFAULT '0.0000' COMMENT '失业比例',
  `injury_rate` decimal(6,4) NOT NULL DEFAULT '0.0000' COMMENT '工伤比例',
  `maternity_rate` decimal(6,4) NOT NULL DEFAULT '0.0000' COMMENT '生育比例',
  `fund_rate` decimal(6,4) NOT NULL DEFAULT '0.0000' COMMENT '公积金比例',
  `base_min` decimal(14,2) DEFAULT NULL COMMENT '基数下限(NULL=不限)',
  `base_max` decimal(14,2) DEFAULT NULL COMMENT '基数上限(NULL=不限)',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='社保公积金方案(多方案,比例可配)';

DROP TABLE IF EXISTS `hrm_job`;

CREATE TABLE `hrm_job` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `job_no` varchar(64) NOT NULL COMMENT '职位编号',
  `title` varchar(200) NOT NULL COMMENT '职位名称',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(200) DEFAULT '' COMMENT '部门名称',
  `position_id` bigint unsigned DEFAULT NULL COMMENT '岗位ID',
  `headcount` int NOT NULL DEFAULT '1' COMMENT '招聘人数',
  `salary_range` varchar(100) DEFAULT '' COMMENT '薪资范围',
  `education` varchar(32) DEFAULT '' COMMENT '学历要求',
  `experience` varchar(100) DEFAULT '' COMMENT '经验要求',
  `description` varchar(2000) DEFAULT '' COMMENT '职位描述',
  `requirement` varchar(2000) DEFAULT '' COMMENT '任职要求',
  `hiring_manager_id` bigint unsigned DEFAULT NULL COMMENT '招聘负责人ID',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1草稿2招聘3暂停4关闭5满编',
  `publish_date` date DEFAULT NULL COMMENT '发布日期',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hrm_job_no` (`job_no`),
  KEY `idx_hrm_job_dept` (`dept_id`),
  KEY `idx_hrm_job_status` (`status`),
  KEY `idx_hrm_job_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='HRM 招聘职位';


DROP TABLE IF EXISTS `hrm_leave`;

CREATE TABLE `hrm_leave` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `leave_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请假单号',
  `employee_id` bigint unsigned NOT NULL COMMENT '员工ID',
  `leave_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '请假类型',
  `start_date` datetime NOT NULL COMMENT '开始时间',
  `end_date` datetime NOT NULL COMMENT '结束时间',
  `duration_days` decimal(5,1) NOT NULL COMMENT '请假天数',
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请假事由',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT '审批状态',
  `approval_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NONE' COMMENT '审批引擎状态(NONE/APPROVING/APPROVED/REJECTED/REVOKED)',
  `approver_id` bigint unsigned DEFAULT NULL COMMENT '审批人ID',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approve_remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批意见',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_hrm_leave_employee_id` (`employee_id`),
  KEY `idx_hrm_leave_status` (`status`),
  KEY `idx_hrm_leave_created_at` (`created_at`),
  KEY `idx_hrm_leave_deleted_at` (`deleted_at`),
  KEY `idx_hrm_leave_approval` (`approval_status`)
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='请假单';


DROP TABLE IF EXISTS `hrm_overtime`;

CREATE TABLE `hrm_overtime` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `overtime_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '加班单号',
  `employee_id` bigint unsigned NOT NULL COMMENT '员工ID',
  `start_date` datetime NOT NULL COMMENT '加班开始时间',
  `end_date` datetime NOT NULL COMMENT '加班结束时间',
  `duration_hours` decimal(5,1) NOT NULL COMMENT '加班时长(小时)',
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '加班事由',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'PENDING' COMMENT '审批状态',
  `approver_id` bigint unsigned DEFAULT NULL COMMENT '审批人ID',
  `approve_time` datetime DEFAULT NULL COMMENT '审批时间',
  `approve_remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批意见',
  `compensate_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'PAY' COMMENT '补偿方式 PAY加班费/TO调休',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_hrm_overtime_employee_id` (`employee_id`),
  KEY `idx_hrm_overtime_status` (`status`),
  KEY `idx_hrm_overtime_created_at` (`created_at`),
  KEY `idx_hrm_overtime_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='加班单';

DROP TABLE IF EXISTS `hrm_payroll`;

CREATE TABLE `hrm_payroll` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `employee_id` bigint unsigned NOT NULL COMMENT '员工ID',
  `year_month` varchar(7) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '年月(2026-08)',
  `base_salary` decimal(12,2) DEFAULT NULL COMMENT '基本工资',
  `position_allow` decimal(12,2) DEFAULT NULL COMMENT '岗位津贴',
  `performance_allow` decimal(12,2) DEFAULT NULL COMMENT '绩效津贴',
  `other_allow` decimal(12,2) DEFAULT NULL COMMENT '其他补贴(餐补/交通)',
  `overtime_pay` decimal(12,2) DEFAULT NULL COMMENT '加班费',
  `gross_pay` decimal(12,2) DEFAULT NULL COMMENT '应发合计',
  `social_ins_deduction` decimal(12,2) DEFAULT NULL COMMENT '社保扣除(个人)',
  `housing_fund_deduction` decimal(12,2) DEFAULT NULL COMMENT '公积金扣除(个人)',
  `absence_deduction` decimal(12,2) DEFAULT NULL COMMENT '缺勤扣除',
  `taxable_income` decimal(12,2) DEFAULT NULL COMMENT '应纳税所得额',
  `tax` decimal(12,2) DEFAULT NULL COMMENT '个人所得税',
  `net_pay` decimal(12,2) DEFAULT NULL COMMENT '实发合计(税后)',
  `items_snapshot` text COLLATE utf8mb4_unicode_ci COMMENT '工资项求值快照JSON',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'DRAFT' COMMENT 'DRAFT/CONFIRMED/PAID',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_payroll` (`employee_id`,`year_month`),
  KEY `idx_hrm_payroll_status` (`status`),
  KEY `idx_hrm_payroll_created_at` (`created_at`),
  KEY `idx_hrm_payroll_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工资条(月度,每员工每月一条)';

DROP TABLE IF EXISTS `hrm_perf_item`;

CREATE TABLE `hrm_perf_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `perf_id` bigint unsigned NOT NULL COMMENT '考核ID',
  `item_name` varchar(200) NOT NULL COMMENT '指标名称',
  `weight` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT '权重(%)',
  `target_desc` varchar(500) DEFAULT '' COMMENT '目标说明',
  `self_score` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '自评得分',
  `review_score` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '上级评分',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_hrm_perfitem_perf` (`perf_id`),
  KEY `idx_hrm_perfitem_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='HRM 考核指标项';


DROP TABLE IF EXISTS `hrm_performance`;

CREATE TABLE `hrm_performance` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `perf_no` varchar(64) NOT NULL COMMENT '考核编号',
  `title` varchar(200) NOT NULL COMMENT '考核标题',
  `employee_id` bigint unsigned NOT NULL COMMENT '被考核人ID',
  `employee_name` varchar(200) DEFAULT '' COMMENT '员工姓名',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `dept_name` varchar(200) DEFAULT '' COMMENT '部门名称',
  `period` varchar(20) DEFAULT '' COMMENT '考核周期',
  `start_date` date NOT NULL COMMENT '考核开始',
  `end_date` date NOT NULL COMMENT '考核结束',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1草稿2进行3自评完成4评审中5完成6取消',
  `reviewer_id` bigint unsigned DEFAULT NULL COMMENT '评审人ID',
  `self_score` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '自评得分',
  `self_comment` varchar(2000) DEFAULT '' COMMENT '自评说明',
  `self_time` datetime DEFAULT NULL COMMENT '自评时间',
  `review_score` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '上级评分',
  `review_comment` varchar(2000) DEFAULT '' COMMENT '评审意见',
  `review_time` datetime DEFAULT NULL COMMENT '评审时间',
  `final_score` decimal(5,1) NOT NULL DEFAULT '0.0' COMMENT '最终得分',
  `grade` varchar(10) DEFAULT '' COMMENT '等级(A/B/C/D)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_hrm_perf_no` (`perf_no`),
  KEY `idx_hrm_perf_employee` (`employee_id`),
  KEY `idx_hrm_perf_dept` (`dept_id`),
  KEY `idx_hrm_perf_period` (`period`),
  KEY `idx_hrm_perf_status` (`status`),
  KEY `idx_hrm_perf_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='HRM 绩效考核';


DROP TABLE IF EXISTS `hrm_position`;

CREATE TABLE `hrm_position` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '岗位名称',
  `code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '岗位编码',
  `department_id` bigint unsigned NOT NULL COMMENT '所属部门ID',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `status` tinyint DEFAULT '1' COMMENT '1正常 0禁用',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_hrm_position_code` (`code`),
  KEY `idx_hrm_position_department_id` (`department_id`),
  KEY `idx_hrm_position_created_at` (`created_at`),
  KEY `idx_hrm_position_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='岗位';


DROP TABLE IF EXISTS `hrm_position_change`;

CREATE TABLE `hrm_position_change` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `employee_id` bigint unsigned NOT NULL COMMENT '员工ID',
  `from_department_id` bigint unsigned DEFAULT NULL COMMENT '原部门ID',
  `to_department_id` bigint unsigned DEFAULT NULL COMMENT '新部门ID',
  `from_position_id` bigint unsigned DEFAULT NULL COMMENT '原岗位ID',
  `to_position_id` bigint unsigned DEFAULT NULL COMMENT '新岗位ID',
  `change_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更类型(字典POSITION_CHANGE_TYPE)',
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更原因',
  `operator_id` bigint unsigned DEFAULT NULL COMMENT '操作人ID',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_hrm_position_change_employee_id` (`employee_id`),
  KEY `idx_hrm_position_change_created_at` (`created_at`),
  KEY `idx_hrm_position_change_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='员工变更履历';


DROP TABLE IF EXISTS `hrm_salary_item`;

CREATE TABLE `hrm_salary_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工资项编码(公式引用,如 BASE_SALARY)',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工资项名称',
  `kind` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'INCOME收入 / DEDUCT扣款 / TAX扣税',
  `formula` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '计算公式(受限四则:数字/项编码/+ - * / 括号/round(x,n);NULL=固定值项)',
  `fixed_amount` decimal(14,2) DEFAULT NULL COMMENT '固定值(无公式时使用)',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序(求值顺序,小在前)',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_status` (`status`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='工资项定义(公式引擎求值)';

DROP TABLE IF EXISTS `hrm_salary_structure`;

CREATE TABLE `hrm_salary_structure` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `employee_id` bigint unsigned NOT NULL COMMENT '员工ID',
  `base_salary` decimal(12,2) DEFAULT NULL COMMENT '基本工资',
  `position_allow` decimal(12,2) DEFAULT NULL COMMENT '岗位津贴',
  `performance_allow` decimal(12,2) DEFAULT NULL COMMENT '绩效津贴',
  `meal_allow` decimal(12,2) DEFAULT NULL COMMENT '餐饮补贴',
  `transport_allow` decimal(12,2) DEFAULT NULL COMMENT '交通补贴',
  `social_ins_rate` decimal(5,4) DEFAULT '0.1050' COMMENT '社保个人比例(养老8%+医疗2%+失业0.5%)',
  `plan_id` bigint unsigned DEFAULT NULL COMMENT '社保方案ID(NULL=沿用内置硬比例)',
  `housing_fund_rate` decimal(5,4) DEFAULT '0.0700' COMMENT '公积金个人比例',
  `social_ins_base` decimal(12,2) DEFAULT NULL COMMENT '社保缴纳基数',
  `housing_fund_base` decimal(12,2) DEFAULT NULL COMMENT '公积金缴纳基数',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_hrm_salary_structure_employee_id` (`employee_id`),
  KEY `idx_hrm_salary_structure_created_at` (`created_at`),
  KEY `idx_hrm_salary_structure_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='薪酬结构(员工的基础工资配置,1:1 with employee)';

DROP TABLE IF EXISTS `hrm_schedule`;

CREATE TABLE `hrm_schedule` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `employee_id` bigint unsigned NOT NULL COMMENT '员工ID',
  `schedule_date` date NOT NULL COMMENT '排班日期',
  `shift_id` bigint unsigned NOT NULL COMMENT '班次ID',
  `source` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_emp_date` (`employee_id`,`schedule_date`),
  KEY `idx_date` (`schedule_date`),
  KEY `idx_shift` (`shift_id`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='排班日历(员工×日期×班次)';

DROP TABLE IF EXISTS `hrm_shift`;

CREATE TABLE `hrm_shift` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '班次名称',
  `start_time` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '上班时间 HH:mm:ss',
  `end_time` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '下班时间 HH:mm:ss',
  `flex_minutes` int NOT NULL DEFAULT '0' COMMENT '弹性分钟数(迟到判定宽限)',
  `cross_day` tinyint NOT NULL DEFAULT '0' COMMENT '是否跨天(1= endTime<startTime)',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考勤班次';

DROP TABLE IF EXISTS `kb_category`;

CREATE TABLE `kb_category` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `parent_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '父分类ID(0=顶级)',
  `name` varchar(100) NOT NULL COMMENT '分类名称',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态(0停用1启用)',
  `creator_id` bigint unsigned NOT NULL COMMENT '创建人ID',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_kb_category_parent` (`parent_id`),
  KEY `idx_kb_category_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='知识库分类';


DROP TABLE IF EXISTS `kb_chunk`;

CREATE TABLE `kb_chunk` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `document_id` bigint unsigned NOT NULL COMMENT '文档ID',
  `seq` int NOT NULL COMMENT '片内序号(从0递增)',
  `content` text COLLATE utf8mb4_general_ci NOT NULL COMMENT '切片正文(纯文本,已剥HTML)',
  `embedding` json DEFAULT NULL COMMENT '嵌入向量JSON([]float64)',
  `vector_dim` int NOT NULL DEFAULT '0' COMMENT '向量维度(换模型后对账用)',
  `status` varchar(16) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'ready' COMMENT 'ready/failed',
  `error` varchar(255) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '失败原因摘要',
  `char_count` int NOT NULL DEFAULT '0' COMMENT '切片字符数',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_kb_chunk_doc_seq` (`document_id`,`seq`),
  KEY `idx_kb_chunk_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='知识库文档切片(P17 RAG)';

DROP TABLE IF EXISTS `kb_document`;

CREATE TABLE `kb_document` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `category_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '分类ID',
  `title` varchar(200) NOT NULL COMMENT '标题',
  `content` longtext COMMENT '内容(HTML快照)',
  `status` varchar(20) NOT NULL DEFAULT 'draft' COMMENT '状态(draft/published)',
  `creator_id` bigint unsigned NOT NULL COMMENT '创建人ID',
  `last_editor_id` bigint unsigned DEFAULT NULL COMMENT '最后编辑人ID',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '浏览次数',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_kb_doc_category` (`category_id`),
  KEY `idx_kb_doc_status` (`status`),
  KEY `idx_kb_doc_creator` (`creator_id`),
  KEY `idx_kb_doc_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='知识库文档';


DROP TABLE IF EXISTS `kb_version`;

CREATE TABLE `kb_version` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `document_id` bigint unsigned NOT NULL COMMENT '文档ID',
  `content` longtext COMMENT '版本内容快照',
  `editor_id` bigint unsigned NOT NULL COMMENT '编辑人ID',
  `version_note` varchar(200) DEFAULT '' COMMENT '版本说明',
  `version_number` int NOT NULL DEFAULT '1' COMMENT '版本号(递增)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_kb_version_doc` (`document_id`),
  KEY `idx_kb_version_editor` (`editor_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='知识库版本历史';

DROP TABLE IF EXISTS `lead_field`;

CREATE TABLE `lead_field` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `resource_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '线索ID',
  `field_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段ID',
  `field_value` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值',
  PRIMARY KEY (`id`),
  KEY `idx_lead_rfv` (`resource_id`,`field_id`,`field_value`),
  KEY `idx_lead_field_field_id` (`field_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='线索自定义字段值(单值)';


DROP TABLE IF EXISTS `lead_field_blob`;

CREATE TABLE `lead_field_blob` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `tenant_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '租户ID(0=平台数据)',
  `resource_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '线索ID',
  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段定义ID(关联sys_module_field)',
  `field_value` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值(大文本)',
  PRIMARY KEY (`id`),
  KEY `idx_lead_field_blob_resource_id` (`resource_id`),
  KEY `idx_lead_field_blob_tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='线索自定义字段大值';


DROP TABLE IF EXISTS `mall_order`;

CREATE TABLE `mall_order` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单号(MO+日期+序号)',
  `customer_id` bigint unsigned DEFAULT NULL COMMENT '关联客户ID',
  `contact_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收货人姓名',
  `contact_phone` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系电话',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '收货地址',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `total_quantity` decimal(14,3) NOT NULL DEFAULT '0.000' COMMENT '总数量',
  `total_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '总金额',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1待处理 2已确认 3已完成 4已取消',
  `psi_order_id` bigint unsigned DEFAULT NULL COMMENT '关联PSI销售单ID',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_mall_order_customer` (`customer_id`),
  KEY `idx_mall_order_phone` (`contact_phone`),
  KEY `idx_mall_order_status` (`status`),
  KEY `idx_mall_order_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商城订单';


DROP TABLE IF EXISTS `mall_order_item`;

CREATE TABLE `mall_order_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL COMMENT '订单ID',
  `product_id` bigint unsigned NOT NULL COMMENT '商品ID(crm_product)',
  `sku_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '规格SKU ID',
  `product_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '商品名称快照',
  `spec` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '规格描述快照',
  `quantity` decimal(14,3) NOT NULL COMMENT '数量',
  `unit_price` decimal(14,2) NOT NULL COMMENT '单价快照',
  `amount` decimal(14,2) NOT NULL COMMENT '金额',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_mall_item_order` (`order_id`),
  KEY `idx_mall_item_deleted` (`deleted_at`),
  KEY `idx_mall_order_item_sku_id` (`sku_id`)
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='商城订单明细';


DROP TABLE IF EXISTS `marketing_account`;

CREATE TABLE `marketing_account` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '账号备注名',
  `channel` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'oceanengine' COMMENT '渠道(oceanengine巨量引擎)',
  `app_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '开放平台应用ID',
  `app_secret` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用Secret(脱敏不回显)',
  `access_token` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '访问令牌(约24h)',
  `refresh_token` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '刷新令牌(约30d)',
  `token_expires_at` datetime DEFAULT NULL COMMENT 'access_token过期时间',
  `refresh_expires_at` datetime DEFAULT NULL COMMENT 'refresh_token过期时间',
  `advertiser_ids` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '已授权广告主ID(逗号分隔)',
  `status` tinyint DEFAULT '0' COMMENT '0待授权 1已授权 2授权失效',
  `enabled` tinyint DEFAULT '1' COMMENT '1启用 0停用',
  `last_sync_at` datetime DEFAULT NULL COMMENT '上次线索同步游标时间',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_marketing_account_status` (`status`,`enabled`),
  KEY `idx_marketing_account_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='营销渠道账号(巨量引擎)';


DROP TABLE IF EXISTS `marketing_lead_log`;

CREATE TABLE `marketing_lead_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `account_id` bigint unsigned NOT NULL COMMENT '渠道账号ID',
  `external_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '外部线索ID(飞鱼clue_id)',
  `lead_id` bigint unsigned DEFAULT NULL COMMENT '入库后的crm_lead.id(重复/失败为NULL)',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '姓名',
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号(可能是虚拟号)',
  `company` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司',
  `campaign_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '广告计划名称',
  `ad_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '广告名称',
  `lead_create_time` datetime DEFAULT NULL COMMENT '留资时间',
  `status` tinyint NOT NULL COMMENT '1已入库 2重复跳过 3失败',
  `detail` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '说明(重复/失败原因)',
  `raw` json DEFAULT NULL COMMENT '原始报文(排查用)',
  `created_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_marketing_lead_log_ext` (`account_id`,`external_id`),
  KEY `idx_marketing_lead_log_status` (`status`),
  KEY `idx_marketing_lead_log_phone` (`phone`),
  KEY `idx_marketing_lead_log_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='营销线索同步日志';

DROP TABLE IF EXISTS `oa_business_trip`;

CREATE TABLE `oa_business_trip` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `trip_no` varchar(64) NOT NULL COMMENT '出差单号',
  `title` varchar(200) NOT NULL COMMENT '出差标题',
  `applicant_id` bigint unsigned NOT NULL COMMENT '申请人ID',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `destination` varchar(200) NOT NULL COMMENT '目的地',
  `purpose` varchar(500) DEFAULT '' COMMENT '出差目的',
  `start_date` date NOT NULL COMMENT '出发日期',
  `end_date` date NOT NULL COMMENT '返回日期',
  `transport` varchar(32) DEFAULT '' COMMENT '交通方式',
  `budget_amount` varchar(32) DEFAULT '' COMMENT '预算金额',
  `description` varchar(1000) DEFAULT '' COMMENT '备注说明',
  `approval_status` varchar(20) NOT NULL DEFAULT 'NONE' COMMENT '审批状态',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_trip_no` (`trip_no`),
  KEY `idx_oa_trip_applicant` (`applicant_id`),
  KEY `idx_oa_trip_approval` (`approval_status`),
  KEY `idx_oa_trip_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 出差申请';


DROP TABLE IF EXISTS `oa_expense`;

CREATE TABLE `oa_expense` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `expense_no` varchar(64) NOT NULL COMMENT '报销单号',
  `title` varchar(200) NOT NULL COMMENT '报销标题',
  `applicant_id` bigint unsigned NOT NULL COMMENT '申请人ID',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `expense_type` varchar(32) NOT NULL COMMENT '费用类型',
  `amount` decimal(14,2) NOT NULL COMMENT '报销总额',
  `occur_date` date DEFAULT NULL COMMENT '费用发生日期',
  `description` varchar(1000) DEFAULT '' COMMENT '说明',
  `approval_status` varchar(20) NOT NULL DEFAULT 'NONE' COMMENT '审批状态',
  `payment_status` tinyint NOT NULL DEFAULT '0' COMMENT '打款状态',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_expense_no` (`expense_no`),
  KEY `idx_oa_expense_applicant` (`applicant_id`),
  KEY `idx_oa_expense_type` (`expense_type`),
  KEY `idx_oa_expense_approval` (`approval_status`),
  KEY `idx_oa_expense_payment` (`payment_status`),
  KEY `idx_oa_expense_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=72 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 报销单';


DROP TABLE IF EXISTS `oa_expense_item`;

CREATE TABLE `oa_expense_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `expense_id` bigint unsigned NOT NULL COMMENT '报销单ID',
  `item_type` varchar(32) DEFAULT '' COMMENT '明细类型',
  `amount` decimal(14,2) NOT NULL COMMENT '金额',
  `occur_date` date DEFAULT NULL COMMENT '发生日期',
  `invoice_no` varchar(64) DEFAULT '' COMMENT '发票号',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_oa_expense_item_expense` (`expense_id`),
  KEY `idx_oa_expense_item_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=78 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 报销明细行';


DROP TABLE IF EXISTS `oa_form_data`;

CREATE TABLE `oa_form_data` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `data_no` varchar(64) NOT NULL COMMENT '数据单号',
  `template_id` bigint unsigned NOT NULL COMMENT '表单模板ID',
  `template_key` varchar(64) DEFAULT '' COMMENT '表单标识(冗余)',
  `template_name` varchar(100) DEFAULT '' COMMENT '表单名称(冗余)',
  `submitter_id` bigint unsigned NOT NULL COMMENT '提交人ID',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `field_values` longtext COMMENT '填写数据JSON',
  `approval_status` varchar(20) NOT NULL DEFAULT 'NONE' COMMENT '审批状态',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_form_data_no` (`data_no`),
  KEY `idx_oa_form_data_template` (`template_id`),
  KEY `idx_oa_form_data_key` (`template_key`),
  KEY `idx_oa_form_data_submitter` (`submitter_id`),
  KEY `idx_oa_form_data_approval` (`approval_status`),
  KEY `idx_oa_form_data_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 自定义表单数据';


DROP TABLE IF EXISTS `oa_form_template`;

CREATE TABLE `oa_form_template` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `form_key` varchar(64) NOT NULL COMMENT '表单标识',
  `name` varchar(100) NOT NULL COMMENT '表单名称',
  `icon` varchar(50) DEFAULT '' COMMENT '图标',
  `description` varchar(500) DEFAULT '' COMMENT '描述',
  `fields_config` longtext COMMENT '字段定义JSON',
  `category` varchar(20) NOT NULL DEFAULT 'non-business' COMMENT '分类(business/non-business)',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态(0停用1启用)',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_form_template_key` (`form_key`),
  KEY `idx_oa_form_template_category` (`category`),
  KEY `idx_oa_form_template_status` (`status`),
  KEY `idx_oa_form_template_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 自定义表单模板';


DROP TABLE IF EXISTS `oa_loan`;

CREATE TABLE `oa_loan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `loan_no` varchar(64) NOT NULL COMMENT '借款单号',
  `title` varchar(200) NOT NULL COMMENT '借款标题',
  `applicant_id` bigint unsigned NOT NULL COMMENT '借款人ID',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `loan_type` varchar(32) NOT NULL COMMENT '借款类型',
  `amount` varchar(32) NOT NULL COMMENT '借款金额',
  `expected_date` date DEFAULT NULL COMMENT '预计还款日期',
  `reason` varchar(500) DEFAULT '' COMMENT '借款事由',
  `approval_status` varchar(20) NOT NULL DEFAULT 'NONE' COMMENT '审批状态',
  `repaid_status` tinyint NOT NULL DEFAULT '0' COMMENT '还款状态(0未还1部分2已还清)',
  `repaid_amount` varchar(32) NOT NULL DEFAULT '0' COMMENT '已还金额',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_loan_no` (`loan_no`),
  KEY `idx_oa_loan_applicant` (`applicant_id`),
  KEY `idx_oa_loan_type` (`loan_type`),
  KEY `idx_oa_loan_approval` (`approval_status`),
  KEY `idx_oa_loan_repaid` (`repaid_status`),
  KEY `idx_oa_loan_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 借款/备用金';


DROP TABLE IF EXISTS `oa_meeting_booking`;

CREATE TABLE `oa_meeting_booking` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `booking_no` varchar(64) NOT NULL COMMENT '预订单号',
  `title` varchar(200) NOT NULL COMMENT '会议标题',
  `room_id` bigint unsigned NOT NULL COMMENT '会议室ID',
  `organizer_id` bigint unsigned NOT NULL COMMENT '预订人ID',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `attendees` int NOT NULL DEFAULT '0' COMMENT '参会人数',
  `topic` varchar(500) DEFAULT '' COMMENT '会议主题/议程',
  `approval_status` varchar(20) NOT NULL DEFAULT 'NONE' COMMENT '审批状态(NONE/APPROVING/APPROVED/REJECTED/REVOKED)',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_meeting_booking_no` (`booking_no`),
  KEY `idx_oa_meeting_booking_room` (`room_id`),
  KEY `idx_oa_meeting_booking_organizer` (`organizer_id`),
  KEY `idx_oa_meeting_booking_approval` (`approval_status`),
  KEY `idx_oa_meeting_booking_time` (`start_time`,`end_time`),
  KEY `idx_oa_meeting_booking_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 会议预订';


DROP TABLE IF EXISTS `oa_meeting_room`;

CREATE TABLE `oa_meeting_room` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(100) NOT NULL COMMENT '会议室名称',
  `location` varchar(200) DEFAULT '' COMMENT '位置',
  `capacity` int NOT NULL DEFAULT '0' COMMENT '容纳人数',
  `equipment` varchar(500) DEFAULT '' COMMENT '设备(逗号分隔)',
  `status` varchar(16) NOT NULL DEFAULT 'ENABLED' COMMENT '状态(ENABLED/DISABLED/MAINTENANCE)',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_oa_meeting_room_status` (`status`),
  KEY `idx_oa_meeting_room_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 会议室';


DROP TABLE IF EXISTS `oa_message`;

CREATE TABLE `oa_message` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `sender_id` bigint unsigned DEFAULT NULL COMMENT '发送人ID(系统消息=0)',
  `receiver_id` bigint unsigned DEFAULT NULL COMMENT '接收人ID',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '内容',
  `content_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'text' COMMENT '内容格式(text/markdown)',
  `is_read` tinyint DEFAULT '0' COMMENT '是否已读(0未读 1已读)',
  `read_time` datetime DEFAULT NULL COMMENT '阅读时间',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_message_sender_id` (`sender_id`),
  KEY `idx_sys_message_receiver_id` (`receiver_id`),
  KEY `idx_sys_message_is_read` (`is_read`),
  KEY `idx_sys_message_created_at` (`created_at`),
  KEY `idx_sys_message_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=1017 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='站内信';






DROP TABLE IF EXISTS `oa_notice`;

CREATE TABLE `oa_notice` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '内容',
  `type` tinyint DEFAULT '1' COMMENT '类型(1通知 2公告)',
  `status` tinyint DEFAULT '0' COMMENT '状态(0草稿 1发布)',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_notice_type` (`type`),
  KEY `idx_sys_notice_status` (`status`),
  KEY `idx_sys_notice_publish_time` (`publish_time`),
  KEY `idx_sys_notice_created_at` (`created_at`),
  KEY `idx_sys_notice_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公告通知';


DROP TABLE IF EXISTS `oa_schedule`;

CREATE TABLE `oa_schedule` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `schedule_no` varchar(64) NOT NULL COMMENT '日程单号',
  `title` varchar(200) NOT NULL COMMENT '标题',
  `event_type` varchar(16) NOT NULL DEFAULT 'OTHER' COMMENT '类型(MEETING/TASK/REMINDER/OUT/OTHER)',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `location` varchar(200) DEFAULT '' COMMENT '地点',
  `content` text COMMENT '内容',
  `remind_type` varchar(16) NOT NULL DEFAULT 'NONE' COMMENT '提醒(NONE/MIN5/MIN15/HOUR1/DAY1)',
  `status` varchar(16) NOT NULL DEFAULT 'PENDING' COMMENT '状态(PENDING/DONE/CANCELED)',
  `creator_id` bigint unsigned NOT NULL COMMENT '创建人ID',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_schedule_no` (`schedule_no`),
  KEY `idx_oa_schedule_creator` (`creator_id`),
  KEY `idx_oa_schedule_type` (`event_type`),
  KEY `idx_oa_schedule_status` (`status`),
  KEY `idx_oa_schedule_time` (`start_time`,`end_time`),
  KEY `idx_oa_schedule_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 日程安排';


DROP TABLE IF EXISTS `oa_seal`;

CREATE TABLE `oa_seal` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(100) NOT NULL COMMENT '印章名称',
  `type` varchar(20) NOT NULL DEFAULT 'OFFICIAL' COMMENT '类型:OFFICIAL公章/CONTRACT合同章/FINANCE财务章/LEGAL法人章/OTHER其他',
  `keeper_id` bigint unsigned DEFAULT NULL COMMENT '保管人ID(sys_user)',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态:1启用 2停用',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_seal_name` (`name`),
  KEY `idx_oa_seal_status` (`status`),
  KEY `idx_oa_seal_keeper` (`keeper_id`),
  KEY `idx_oa_seal_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 印章台账';

DROP TABLE IF EXISTS `oa_seal_application`;

CREATE TABLE `oa_seal_application` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `application_no` varchar(64) NOT NULL COMMENT '用印申请单号',
  `title` varchar(200) NOT NULL COMMENT '申请标题',
  `applicant_id` bigint unsigned NOT NULL COMMENT '申请人ID',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `seal_id` bigint unsigned NOT NULL COMMENT '印章ID',
  `reason` varchar(500) NOT NULL COMMENT '用印事由',
  `document_name` varchar(200) DEFAULT '' COMMENT '文件名称',
  `copies` int NOT NULL DEFAULT '1' COMMENT '份数',
  `seal_date` datetime NOT NULL COMMENT '用印日期',
  `approval_status` varchar(20) NOT NULL DEFAULT 'NONE' COMMENT '审批状态',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_seal_application_no` (`application_no`),
  KEY `idx_oa_seal_application_approval` (`approval_status`),
  KEY `idx_oa_seal_application_applicant` (`applicant_id`),
  KEY `idx_oa_seal_application_seal` (`seal_id`),
  KEY `idx_oa_seal_application_dept` (`dept_id`),
  KEY `idx_oa_seal_application_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 用印申请单';

DROP TABLE IF EXISTS `oa_vehicle`;

CREATE TABLE `oa_vehicle` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `plate_no` varchar(20) NOT NULL COMMENT '车牌号',
  `vehicle_model` varchar(100) DEFAULT '' COMMENT '车型',
  `seats` int NOT NULL DEFAULT '5' COMMENT '座位数',
  `status` varchar(20) NOT NULL DEFAULT 'IDLE' COMMENT '状态:IDLE空闲/IN_USE使用中/MAINTENANCE维修中/DISABLED停用',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '责任人ID(sys_user)',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_vehicle_plate_no` (`plate_no`),
  KEY `idx_oa_vehicle_status` (`status`),
  KEY `idx_oa_vehicle_owner` (`owner_id`),
  KEY `idx_oa_vehicle_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 车辆台账';

DROP TABLE IF EXISTS `oa_vehicle_application`;

CREATE TABLE `oa_vehicle_application` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `application_no` varchar(64) NOT NULL COMMENT '用车申请单号',
  `title` varchar(200) NOT NULL COMMENT '申请标题',
  `applicant_id` bigint unsigned NOT NULL COMMENT '申请人ID',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `vehicle_id` bigint unsigned NOT NULL COMMENT '车辆ID',
  `reason` varchar(500) NOT NULL COMMENT '用车事由',
  `start_time` datetime NOT NULL COMMENT '出发时间',
  `end_time` datetime NOT NULL COMMENT '预计归还时间',
  `passengers` int NOT NULL DEFAULT '1' COMMENT '随行人数',
  `destination` varchar(200) DEFAULT '' COMMENT '目的地',
  `approval_status` varchar(20) NOT NULL DEFAULT 'NONE' COMMENT '审批状态',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '业务状态:1用车中 2已归还',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_vehicle_application_no` (`application_no`),
  KEY `idx_oa_vehicle_application_approval` (`approval_status`),
  KEY `idx_oa_vehicle_application_applicant` (`applicant_id`),
  KEY `idx_oa_vehicle_application_vehicle` (`vehicle_id`),
  KEY `idx_oa_vehicle_application_dept` (`dept_id`),
  KEY `idx_oa_vehicle_application_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 用车申请单';

DROP TABLE IF EXISTS `oa_work_log`;

CREATE TABLE `oa_work_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `log_no` varchar(64) NOT NULL COMMENT '日志单号',
  `log_type` varchar(16) NOT NULL DEFAULT 'DAILY' COMMENT '类型(DAILY/WEEKLY/MONTHLY)',
  `log_date` date NOT NULL COMMENT '日志日期',
  `content` text COMMENT '今日完成',
  `plan` text COMMENT '明日计划',
  `problems` text COMMENT '遇到问题',
  `creator_id` bigint unsigned NOT NULL COMMENT '填写人ID',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_oa_work_log_no` (`log_no`),
  KEY `idx_oa_work_log_creator` (`creator_id`),
  KEY `idx_oa_work_log_dept` (`dept_id`),
  KEY `idx_oa_work_log_type` (`log_type`),
  KEY `idx_oa_work_log_date` (`log_date`),
  KEY `idx_oa_work_log_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='OA 工作日志';


DROP TABLE IF EXISTS `open_webhook`;

CREATE TABLE `open_webhook` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '端点名称',
  `url` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '投递目标 URL(仅 http/https)',
  `secret` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'HMAC-SHA256 签名密钥(敏感,创建时缺省服务端生成)',
  `events` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '订阅事件,逗号分隔,空=订阅全部',
  `status` tinyint DEFAULT '1' COMMENT '1启用 0停用',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_open_webhook_status` (`status`),
  KEY `idx_open_webhook_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='开放平台 Webhook 端点配置';


DROP TABLE IF EXISTS `open_webhook_event`;

CREATE TABLE `open_webhook_event` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `webhook_id` bigint unsigned NOT NULL COMMENT '目标 webhook',
  `event_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件类型',
  `payload` text COLLATE utf8mb4_unicode_ci COMMENT '事件载荷(JSON快照)',
  `status` tinyint DEFAULT '0' COMMENT '0待投递 1成功 2失败重试中 3死信',
  `retry_count` int DEFAULT '0' COMMENT '已尝试次数',
  `max_retries` int DEFAULT '5' COMMENT '最大尝试次数',
  `next_retry_at` datetime(3) DEFAULT NULL COMMENT '下次投递时间',
  `last_http_status` int DEFAULT NULL COMMENT '最近一次HTTP状态码',
  `last_error` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近一次错误',
  `delivered_at` datetime(3) DEFAULT NULL COMMENT '投递成功时间',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_owe_whs` (`webhook_id`,`status`),
  KEY `idx_owe_snr` (`status`,`next_retry_at`),
  KEY `idx_owe_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Webhook投递日志';

