  `field_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段定义ID(关联sys_module_field)',
  `field_value` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段值',
  PRIMARY KEY (`id`),
