DROP TABLE IF EXISTS `proj_project`;

CREATE TABLE `proj_project` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `project_no` varchar(64) NOT NULL COMMENT '项目编号',
  `name` varchar(200) NOT NULL COMMENT '项目名称',
  `description` varchar(2000) DEFAULT '' COMMENT '项目描述',
  `customer_id` bigint unsigned DEFAULT NULL COMMENT '关联客户ID',
  `customer_name` varchar(200) DEFAULT '' COMMENT '客户名称',
  `contract_id` bigint unsigned DEFAULT NULL COMMENT '关联合同ID',
  `manager_id` bigint unsigned DEFAULT NULL COMMENT '项目经理ID',
  `member_ids` varchar(500) DEFAULT '' COMMENT '成员ID(逗号分隔)',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1规划2进行3暂停4完成5取消',
  `priority` tinyint NOT NULL DEFAULT '2' COMMENT '1低2中3高4紧急',
  `start_date` date DEFAULT NULL COMMENT '开始日期',
  `end_date` date DEFAULT NULL COMMENT '计划完成日期',
  `progress` tinyint NOT NULL DEFAULT '0' COMMENT '进度(0-100)',
  `tags` varchar(200) DEFAULT '' COMMENT '标签',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proj_no` (`project_no`),
  KEY `idx_proj_customer` (`customer_id`),
  KEY `idx_proj_contract` (`contract_id`),
  KEY `idx_proj_manager` (`manager_id`),
  KEY `idx_proj_status` (`status`),
  KEY `idx_proj_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目';


DROP TABLE IF EXISTS `proj_task`;

CREATE TABLE `proj_task` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `project_id` bigint unsigned NOT NULL COMMENT '所属项目ID',
  `title` varchar(200) NOT NULL COMMENT '任务标题',
  `description` varchar(2000) DEFAULT '' COMMENT '任务描述',
  `assignee_id` bigint unsigned DEFAULT NULL COMMENT '负责人ID',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1待办2进行3完成4取消',
  `priority` tinyint NOT NULL DEFAULT '2' COMMENT '1低2中3高4紧急',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序',
  `due_date` date DEFAULT NULL COMMENT '截止日期',
  `done_at` datetime DEFAULT NULL COMMENT '完成时间',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_task_project` (`project_id`),
  KEY `idx_task_assignee` (`assignee_id`),
  KEY `idx_task_status` (`status`),
  KEY `idx_task_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目任务';


DROP TABLE IF EXISTS `psi_asset`;

CREATE TABLE `psi_asset` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `asset_no` varchar(64) NOT NULL COMMENT '资产编号',
  `name` varchar(200) NOT NULL COMMENT '资产名称',
  `category` varchar(32) DEFAULT '' COMMENT '类别',
  `spec` varchar(200) DEFAULT '' COMMENT '规格型号',
  `serial_no` varchar(100) DEFAULT '' COMMENT '序列号',
  `warehouse_id` bigint unsigned DEFAULT NULL COMMENT '存放仓库ID',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '使用部门ID',
  `owner_id` bigint unsigned DEFAULT NULL COMMENT '使用人ID',
  `purchase_date` date DEFAULT NULL COMMENT '采购日期',
  `purchase_price` varchar(32) DEFAULT '' COMMENT '采购价格',
  `depreciation` varchar(32) NOT NULL DEFAULT '0' COMMENT '已折旧',
  `net_value` varchar(32) DEFAULT '' COMMENT '净值',
  `useful_life` int NOT NULL DEFAULT '0' COMMENT '使用年限(月)',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1使用2闲置3维修4报废5丢失',
  `location` varchar(200) DEFAULT '' COMMENT '存放位置',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_psi_asset_no` (`asset_no`),
  KEY `idx_psi_asset_category` (`category`),
  KEY `idx_psi_asset_dept` (`dept_id`),
  KEY `idx_psi_asset_owner` (`owner_id`),
  KEY `idx_psi_asset_status` (`status`),
  KEY `idx_psi_asset_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='PSI 固定资产';


DROP TABLE IF EXISTS `psi_purchase_order`;

CREATE TABLE `psi_purchase_order` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '采购单号',
  `supplier_id` bigint unsigned NOT NULL COMMENT '供应商ID',
