  `discount_amount` decimal(14,2) DEFAULT '0.00' COMMENT '优惠金额',
  `status` tinyint DEFAULT '1' COMMENT '1待入库 2已入库 3已关闭',
  `approval_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT 'NONE' COMMENT '审批状态(引擎写回)',
  `operator_id` bigint unsigned DEFAULT NULL COMMENT '经办人ID',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
