  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_psi_purchase_order_supplier_id` (`supplier_id`),
  KEY `idx_psi_purchase_order_warehouse_id` (`warehouse_id`),
  KEY `idx_psi_purchase_order_status` (`status`),
  KEY `idx_psi_purchase_order_approval_status` (`approval_status`),
  KEY `idx_psi_purchase_order_operator_id` (`operator_id`),
  KEY `idx_psi_purchase_order_created_at` (`created_at`),
  KEY `idx_psi_purchase_order_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=78 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='采购订单';


DROP TABLE IF EXISTS `psi_purchase_order_detail`;

