  `safety_stock` decimal(14,3) DEFAULT '0.000' COMMENT '安全库存(预警阈值)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sku_warehouse` (`sku_id`,`warehouse_id`),
  KEY `idx_psi_stock_product_id` (`product_id`),
  KEY `idx_psi_stock_warehouse_id` (`warehouse_id`),
  KEY `idx_psi_stock_created_at` (`created_at`),
  KEY `idx_psi_stock_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='库存结余(按 商品+仓库 维度)';


DROP TABLE IF EXISTS `psi_stock_in_order`;

CREATE TABLE `psi_stock_in_order` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '入库单号',
  `warehouse_id` bigint unsigned NOT NULL COMMENT '入库仓库ID',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '子类型(INIT/PROFIT/GIFT/OTHER)',
  `order_date` datetime DEFAULT NULL COMMENT '单据日期',
  `total_amount` decimal(14,2) DEFAULT '0.00' COMMENT '合计金额',
  `status` tinyint DEFAULT '1' COMMENT '1待生效 2已生效',
  `operator_id` bigint unsigned DEFAULT NULL COMMENT '经办人ID',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_psi_stock_in_order_warehouse_id` (`warehouse_id`),
  KEY `idx_psi_stock_in_order_biz_type` (`biz_type`),
  KEY `idx_psi_stock_in_order_status` (`status`),
  KEY `idx_psi_stock_in_order_operator_id` (`operator_id`),
  KEY `idx_psi_stock_in_order_created_at` (`created_at`),
  KEY `idx_psi_stock_in_order_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='其他入库单(盘盈/赠品/期初/其他)';


DROP TABLE IF EXISTS `psi_stock_in_order_detail`;

CREATE TABLE `psi_stock_in_order_detail` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_id` bigint unsigned NOT NULL COMMENT '入库单ID',
  `product_id` bigint unsigned NOT NULL COMMENT '商品ID',
  `sku_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '规格SKU ID',
  `quantity` decimal(14,3) NOT NULL COMMENT '入库数量',
  `unit_cost` decimal(14,2) DEFAULT NULL COMMENT '单位成本',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_order` (`order_id`),
  KEY `idx_psi_stock_in_order_detail_product_id` (`product_id`),
  KEY `idx_psi_stock_in_order_detail_created_at` (`created_at`),
  KEY `idx_psi_stock_in_order_detail_deleted_at` (`deleted_at`),
  KEY `idx_psi_stock_in_order_detail_sku_id` (`sku_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='其他入库明细';


DROP TABLE IF EXISTS `psi_stock_movement`;

CREATE TABLE `psi_stock_movement` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型(PURCHASE_IN/SALES_OUT/...)',
  `biz_order_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源单据类型',
  `biz_order_id` bigint unsigned DEFAULT NULL COMMENT '来源单据ID',
  `biz_order_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源单据编号',
  `product_id` bigint unsigned NOT NULL COMMENT '商品ID',
  `sku_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '规格SKU ID',
  `warehouse_id` bigint unsigned NOT NULL COMMENT '仓库ID',
  `in_qty` decimal(14,3) DEFAULT '0.000' COMMENT '入库数量',
  `out_qty` decimal(14,3) DEFAULT '0.000' COMMENT '出库数量',
  `balance_after` decimal(14,3) DEFAULT NULL COMMENT '变动后结余',
  `unit_cost` decimal(14,2) DEFAULT NULL COMMENT '单位成本(入库用)',
  `operator_id` bigint unsigned DEFAULT NULL COMMENT '操作人ID',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_psi_stock_movement_biz_type` (`biz_type`),
  KEY `idx_psi_stock_movement_biz_order_type` (`biz_order_type`),
  KEY `idx_psi_stock_movement_biz_order_id` (`biz_order_id`),
  KEY `idx_psi_stock_movement_biz_order_no` (`biz_order_no`),
  KEY `idx_psi_stock_movement_product_id` (`product_id`),
  KEY `idx_psi_stock_movement_warehouse_id` (`warehouse_id`),
  KEY `idx_psi_stock_movement_operator_id` (`operator_id`),
  KEY `idx_psi_stock_movement_created_at` (`created_at`),
  KEY `idx_psi_stock_movement_deleted_at` (`deleted_at`),
  KEY `idx_psi_stock_movement_sku_id` (`sku_id`)
) ENGINE=InnoDB AUTO_INCREMENT=136 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='库存出入库流水(append-only,只增不改不删)';


DROP TABLE IF EXISTS `psi_stock_out_order`;

CREATE TABLE `psi_stock_out_order` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '出库单号',
  `warehouse_id` bigint unsigned NOT NULL COMMENT '出库仓库ID',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '子类型(LOSS/SCRAP/USE/OTHER)',
  `order_date` datetime DEFAULT NULL COMMENT '单据日期',
  `status` tinyint DEFAULT '1' COMMENT '1待生效 2已生效',
  `operator_id` bigint unsigned DEFAULT NULL COMMENT '经办人ID',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`order_no`),
  KEY `idx_psi_stock_out_order_warehouse_id` (`warehouse_id`),
  KEY `idx_psi_stock_out_order_biz_type` (`biz_type`),
  KEY `idx_psi_stock_out_order_status` (`status`),
  KEY `idx_psi_stock_out_order_operator_id` (`operator_id`),
  KEY `idx_psi_stock_out_order_created_at` (`created_at`),
  KEY `idx_psi_stock_out_order_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='其他出库单(盘亏/报损/领用/其他)';


DROP TABLE IF EXISTS `psi_stock_out_order_detail`;

CREATE TABLE `psi_stock_out_order_detail` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_id` bigint unsigned NOT NULL COMMENT '出库单ID',
  `product_id` bigint unsigned NOT NULL COMMENT '商品ID',
  `sku_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '规格SKU ID',
  `quantity` decimal(14,3) NOT NULL COMMENT '出库数量',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_order` (`order_id`),
  KEY `idx_psi_stock_out_order_detail_product_id` (`product_id`),
  KEY `idx_psi_stock_out_order_detail_created_at` (`created_at`),
  KEY `idx_psi_stock_out_order_detail_deleted_at` (`deleted_at`),
  KEY `idx_psi_stock_out_order_detail_sku_id` (`sku_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='其他出库明细';


DROP TABLE IF EXISTS `psi_stock_transfer`;

CREATE TABLE `psi_stock_transfer` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `transfer_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '调拨单号(DB+日期+纳秒尾)',
  `from_warehouse_id` bigint unsigned NOT NULL COMMENT '调出仓库ID',
  `to_warehouse_id` bigint unsigned NOT NULL COMMENT '调入仓库ID',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1在途 2完成 3已作废',
  `transfer_date` datetime DEFAULT NULL COMMENT '调拨日期',
  `operator_id` bigint unsigned DEFAULT NULL COMMENT '经办人ID',
  `execute_time` datetime DEFAULT NULL COMMENT '执行时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '调拨说明',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`transfer_no`),
  KEY `idx_from_warehouse` (`from_warehouse_id`),
  KEY `idx_to_warehouse` (`to_warehouse_id`),
  KEY `idx_status` (`status`),
  KEY `idx_operator` (`operator_id`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='库存调拨单';

DROP TABLE IF EXISTS `psi_stock_transfer_item`;

CREATE TABLE `psi_stock_transfer_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `transfer_id` bigint unsigned NOT NULL COMMENT '调拨单ID',
  `product_id` bigint unsigned NOT NULL COMMENT '商品ID',
  `sku_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '规格SKU ID(0=历史数据未指定)',
  `quantity` decimal(14,3) NOT NULL COMMENT '调拨数量',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_transfer` (`transfer_id`),
  KEY `idx_product` (`product_id`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='库存调拨明细';

DROP TABLE IF EXISTS `psi_stocktake`;

CREATE TABLE `psi_stocktake` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `stocktake_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '盘点单号(PD+日期+纳秒尾)',
  `warehouse_id` bigint unsigned NOT NULL COMMENT '盘点仓库ID',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1盘点中 2已确认 3已作废',
  `take_date` datetime DEFAULT NULL COMMENT '盘点日期',
  `operator_id` bigint unsigned DEFAULT NULL COMMENT '发起人ID',
  `confirm_time` datetime DEFAULT NULL COMMENT '确认时间',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '盘点说明',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_order_no` (`stocktake_no`),
  KEY `idx_warehouse` (`warehouse_id`),
  KEY `idx_status` (`status`),
  KEY `idx_operator` (`operator_id`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='库存盘点单';

DROP TABLE IF EXISTS `psi_stocktake_item`;

CREATE TABLE `psi_stocktake_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `stocktake_id` bigint unsigned NOT NULL COMMENT '盘点单ID',
  `product_id` bigint unsigned NOT NULL COMMENT '商品ID',
  `sku_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '规格SKU ID(0=历史数据未指定)',
  `expected_qty` decimal(14,3) NOT NULL COMMENT '账面数量(发起时快照)',
  `actual_qty` decimal(14,3) DEFAULT NULL COMMENT '实盘数量(未盘为NULL)',
  `diff_qty` decimal(14,3) NOT NULL DEFAULT '0.000' COMMENT '差异数量(确认时计算 actual-expected)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL,
  `updated_at` datetime(3) DEFAULT NULL,
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_stocktake` (`stocktake_id`),
  KEY `idx_product` (`product_id`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='库存盘点明细';

DROP TABLE IF EXISTS `psi_supplier`;

CREATE TABLE `psi_supplier` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '供应商名称',
  `supplier_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '供应商编号',
  `contact_person` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人',
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `email` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地址',
  `bank_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '开户银行',
  `bank_account` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '银行账号',
  `status` tinyint DEFAULT '1' COMMENT '1启用 2停用',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_psi_supplier_name` (`name`),
  KEY `idx_psi_supplier_status` (`status`),
  KEY `idx_psi_supplier_created_at` (`created_at`),
  KEY `idx_psi_supplier_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=74 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='供应商档案(采购卖方)';


DROP TABLE IF EXISTS `psi_warehouse`;

CREATE TABLE `psi_warehouse` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '仓库编码',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '仓库名称',
  `address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '仓库地址',
  `manager_id` bigint unsigned DEFAULT NULL COMMENT '负责人ID',
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  `status` tinyint DEFAULT '1' COMMENT '1启用 2停用',
  `is_default` tinyint DEFAULT '0' COMMENT '0否 1默认仓库',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_psi_warehouse_name` (`name`),
  KEY `idx_psi_warehouse_status` (`status`),
  KEY `idx_psi_warehouse_created_at` (`created_at`),
  KEY `idx_psi_warehouse_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='仓库';


DROP TABLE IF EXISTS `stage_config`;

CREATE TABLE `stage_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型(OPPORTUNITY/CONTRACT)',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置名称',
  `stages_json` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '阶段数组JSON',
  `enabled` tinyint DEFAULT '1' COMMENT '是否启用',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_stage_config_biz_type` (`biz_type`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='阶段配置';


DROP TABLE IF EXISTS `stage_record`;

CREATE TABLE `stage_record` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `biz_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型',
  `resource_id` bigint unsigned NOT NULL COMMENT '资源ID(商机/合同ID)',
  `from_stage` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原阶段(首次进入为空)',
  `to_stage` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '新阶段',
  `operator_id` bigint unsigned NOT NULL COMMENT '操作人',
  `reason` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原因',
  PRIMARY KEY (`id`),
  KEY `idx_stage_record_biz_type` (`biz_type`),
  KEY `idx_stage_record_resource_id` (`resource_id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='阶段变更记录(追加写,不软删除)';


DROP TABLE IF EXISTS `sys_api`;

CREATE TABLE `sys_api` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '接口路径',
  `method` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'HTTP方法',
  `group` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '接口分组/模块',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_api_created_at` (`created_at`),
  KEY `idx_sys_api_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=818 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='接口注册表';







DROP TABLE IF EXISTS `sys_api_key`;

CREATE TABLE `sys_api_key` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint unsigned NOT NULL COMMENT '关联用户ID',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Key名称(如''我的CLI'')',
  `key_prefix` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前缀(qzt_)',
  `key_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SHA256 hash',
  `last_used_at` datetime DEFAULT NULL COMMENT '最后使用时间',
  `last_used_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最后使用IP',
  `expires_at` datetime DEFAULT NULL COMMENT '过期时间(空=永不过期)',
  `status` tinyint DEFAULT '1' COMMENT '1启用0禁用',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  `toolsets` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '可用工具集(逗号分隔,空=全部)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_api_key_key_hash` (`key_hash`),
  KEY `idx_sys_api_key_user_id` (`user_id`),
  KEY `idx_sys_api_key_status` (`status`),
  KEY `idx_sys_api_key_created_at` (`created_at`),
  KEY `idx_sys_api_key_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=900034 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户 API Key';


DROP TABLE IF EXISTS `sys_attachment`;

CREATE TABLE `sys_attachment` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `biz_type` varchar(32) NOT NULL COMMENT '业务类型(CUSTOMER/CONTRACT/OPPORTUNITY/EMPLOYEE/...)',
  `resource_id` bigint unsigned NOT NULL COMMENT '资源ID',
  `file_name` varchar(255) NOT NULL COMMENT '原始文件名',
  `object_key` varchar(500) NOT NULL COMMENT '存储路径(OSS key 或本地相对路径)',
  `url` varchar(500) NOT NULL COMMENT '访问URL(公共=明文直链;私有=objectKey,需走/api/file/sign)',
  `size` bigint NOT NULL DEFAULT '0' COMMENT '文件大小(字节)',
  `content_type` varchar(100) NOT NULL DEFAULT '' COMMENT 'MIME类型',
  `visibility` varchar(10) NOT NULL DEFAULT 'private' COMMENT 'public/private',
  `uploader_id` bigint unsigned NOT NULL COMMENT '上传人ID',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3) COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '软删除',
  PRIMARY KEY (`id`),
  KEY `idx_attach_biz` (`biz_type`,`resource_id`),
  KEY `idx_attach_uploader` (`uploader_id`),
  KEY `idx_attach_deleted` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='通用附件表';


DROP TABLE IF EXISTS `sys_config`;

CREATE TABLE `sys_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `group` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分组',
  `key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置键',
  `name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '显示名',
  `value` text COLLATE utf8mb4_unicode_ci COMMENT '值(统一字符串存储)',
  `type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT 'string' COMMENT 'string/int/bool/float/json/text/select',
  `options` text COLLATE utf8mb4_unicode_ci COMMENT 'select 选项或校验规则(JSON)',
  `is_public` tinyint(1) DEFAULT '0' COMMENT '是否免鉴权可读',
  `editable` tinyint(1) DEFAULT '1' COMMENT '是否允许后台编辑',
  `builtin` tinyint(1) DEFAULT '0' COMMENT '内置(不可删除)',
  `sort` bigint DEFAULT '0' COMMENT '排序号',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_config_key` (`key`),
  KEY `idx_sys_config_group` (`group`),
  KEY `idx_sys_config_created_at` (`created_at`),
  KEY `idx_sys_config_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统配置(运行时参数键值对)';


DROP TABLE IF EXISTS `sys_dict`;

CREATE TABLE `sys_dict` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字典名称',
  `code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字典编码',
  `status` tinyint DEFAULT '1' COMMENT '1-启用 0-禁用',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  `sort` bigint DEFAULT '0' COMMENT '排序',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_dict_code` (`code`),
  KEY `idx_sys_dict_created_at` (`created_at`),
  KEY `idx_sys_dict_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=39 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='字典';


DROP TABLE IF EXISTS `sys_dict_item`;

CREATE TABLE `sys_dict_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `dict_id` bigint unsigned NOT NULL COMMENT '所属字典ID',
  `label` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '显示文本',
  `value` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '存储值',
  `sort` bigint DEFAULT '0' COMMENT '排序号',
  `status` tinyint DEFAULT '1' COMMENT '1-启用 0-禁用',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_dict_item_dict_id` (`dict_id`),
  KEY `idx_sys_dict_item_created_at` (`created_at`),
  KEY `idx_sys_dict_item_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_sys_dict_items` FOREIGN KEY (`dict_id`) REFERENCES `sys_dict` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=153 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='字典项';



DROP TABLE IF EXISTS `sys_field_change_log`;

CREATE TABLE `sys_field_change_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tenant_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '租户ID(0=平台数据)',
  `biz_type` varchar(32) NOT NULL COMMENT '业务类型(CUSTOMER/LEAD/OPPORTUNITY/CONTRACT)',
  `resource_id` bigint unsigned NOT NULL COMMENT '资源ID',
  `field` varchar(64) NOT NULL COMMENT '字段列名',
  `field_label` varchar(64) DEFAULT NULL COMMENT '字段中文名',
  `old_value` text COMMENT '旧值',
  `new_value` text COMMENT '新值',
  `operator_id` bigint unsigned NOT NULL COMMENT '操作人ID',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_biz_resource` (`biz_type`,`resource_id`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_sys_field_change_log_tenant_id` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=63 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='字段变更日志';


DROP TABLE IF EXISTS `sys_job`;

CREATE TABLE `sys_job` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `job_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务名称',
  `job_group` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务分组',
  `cron_expression` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Cron表达式(6段式 秒分时日月周)',
  `bean_class` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '执行处理器注册名',
  `status` tinyint DEFAULT '1' COMMENT '状态(0暂停 1运行)',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_job_job_group` (`job_group`),
  KEY `idx_sys_job_status` (`status`),
  KEY `idx_sys_job_created_at` (`created_at`),
  KEY `idx_sys_job_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='定时任务配置';


DROP TABLE IF EXISTS `sys_job_log`;

CREATE TABLE `sys_job_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `job_id` bigint unsigned NOT NULL COMMENT '任务ID',
  `job_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务名称',
  `job_group` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '任务分组',
  `bean_class` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '执行处理器',
  `trigger_source` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '触发来源(SCHEDULE/MANUAL)',
  `status` tinyint DEFAULT NULL COMMENT '执行状态(1成功 0失败)',
  `message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '执行消息',
  `exception_info` text COLLATE utf8mb4_unicode_ci COMMENT '异常堆栈',
  `cost_time` bigint DEFAULT NULL COMMENT '耗时(ms)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_job_log_job_id` (`job_id`),
  KEY `idx_sys_job_log_status` (`status`),
  KEY `idx_sys_job_log_created_at` (`created_at`),
  KEY `idx_sys_job_log_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=16207 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='任务执行日志';




































































































































































DROP TABLE IF EXISTS `sys_llm_usage`;

CREATE TABLE `sys_llm_usage` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `user_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '发起用户ID(0=系统定时任务)',
  `feature` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '功能标识,如 geo.monitor/assessment.report',
  `provider` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '供应商标识(如 openai-compat)',
  `model` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '模型名',
  `prompt_tokens` int unsigned NOT NULL DEFAULT '0' COMMENT '输入token数',
  `completion_tokens` int unsigned NOT NULL DEFAULT '0' COMMENT '输出token数',
  `total_tokens` int unsigned NOT NULL DEFAULT '0' COMMENT '总token数',
  `from_cache` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否命中响应缓存(未消耗供应商额度)',
  `latency_ms` int unsigned NOT NULL DEFAULT '0' COMMENT '调用耗时(毫秒)',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ok' COMMENT 'ok=成功 error=失败',
  `err_msg` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '失败原因摘要(截断,不含prompt)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_feature_created` (`user_id`,`feature`,`created_at`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=163 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='LLM 网关调用记账';



DROP TABLE IF EXISTS `sys_login_log`;

CREATE TABLE `sys_login_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint unsigned DEFAULT '0' COMMENT '用户ID(失败登录为0)',
  `username` varchar(64) DEFAULT NULL COMMENT '用户名',
  `action` varchar(32) DEFAULT NULL COMMENT '动作(登录/登出)',
  `success` tinyint(1) DEFAULT '0' COMMENT '是否成功',
  `client_ip` varchar(64) DEFAULT NULL COMMENT '客户端IP',
  `user_agent` varchar(255) DEFAULT NULL COMMENT 'User-Agent',
  `error_msg` text COMMENT '失败原因',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_username` (`username`),
  KEY `idx_success` (`success`),
  KEY `idx_client_ip` (`client_ip`)
) ENGINE=InnoDB AUTO_INCREMENT=2467 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='登录日志';


























DROP TABLE IF EXISTS `sys_menu`;

CREATE TABLE `sys_menu` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `parent_id` bigint unsigned DEFAULT '0' COMMENT '父菜单ID',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前端路由路径',
  `component` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前端组件路径(对应pages下文件)',
  `icon` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '菜单图标',
  `sort` bigint DEFAULT '0' COMMENT '排序号',
  `type` tinyint DEFAULT NULL COMMENT '0-目录 1-菜单 2-按钮',
  `permission` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '权限标识',
  `visible` tinyint DEFAULT '1' COMMENT '1-显示 0-隐藏',
  `status` tinyint DEFAULT '1' COMMENT '1-正常 0-禁用',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_menu_created_at` (`created_at`),
  KEY `idx_sys_menu_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2318 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='菜单/权限节点';





DROP TABLE IF EXISTS `sys_menu_api`;

CREATE TABLE `sys_menu_api` (
  `sys_menu_id` bigint unsigned NOT NULL COMMENT '菜单ID',
  `sys_api_id` bigint unsigned NOT NULL COMMENT 'API ID',
  PRIMARY KEY (`sys_menu_id`,`sys_api_id`),
  KEY `fk_sys_menu_api_sys_api` (`sys_api_id`),
  CONSTRAINT `fk_sys_menu_api_sys_api` FOREIGN KEY (`sys_api_id`) REFERENCES `sys_api` (`id`),
  CONSTRAINT `fk_sys_menu_api_sys_menu` FOREIGN KEY (`sys_menu_id`) REFERENCES `sys_menu` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='菜单-API关联表';







DROP TABLE IF EXISTS `sys_module_field`;

CREATE TABLE `sys_module_field` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `form_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属表单ID',
  `internal_key` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字段内置Key',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段名称',
  `type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字段类型',
  `mobile` tinyint DEFAULT '0' COMMENT '是否移动端',
  `pos` bigint DEFAULT '0' COMMENT '排序',
  `readable` tinyint DEFAULT '1' COMMENT '是否可见',
  `editable` tinyint DEFAULT '1' COMMENT '是否可编辑',
  `convert_target_field` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '转化映射目标字段ID(线索字段→客户字段)',
  PRIMARY KEY (`id`),
  KEY `idx_form` (`form_id`),
  KEY `idx_form_internal` (`internal_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='字段定义(主信息)';


DROP TABLE IF EXISTS `sys_module_field_blob`;

CREATE TABLE `sys_module_field_blob` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `prop` text COLLATE utf8mb4_unicode_ci COMMENT '字段属性JSON',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='字段定义的大属性(选项/校验/默认值/联动规则,JSON)';


DROP TABLE IF EXISTS `sys_module_form`;

CREATE TABLE `sys_module_form` (
  `id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键ID',
  `form_key` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模块标识',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '表单名称',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_module_form_form_key` (`form_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='模块表单配置';


DROP TABLE IF EXISTS `sys_oauth_config`;

CREATE TABLE `sys_oauth_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `provider` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '渠道(wecom/ding/feishu)',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '显示名称(如''企业微信扫码登录'')',
  `enabled` tinyint DEFAULT '0' COMMENT '是否启用(1启用0禁用)',
  `app_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用ID(corp_id/app_key)',
  `app_secret` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用Secret(脱敏,不返回)',
  `agent_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'AgentID(企业微信用)',
  `redirect_uri` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扫码登录回调地址',
  `extra` text COLLATE utf8mb4_unicode_ci COMMENT '扩展配置JSON',
  `sort` bigint DEFAULT '0' COMMENT '排序号',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_oauth_config_provider` (`provider`),
  KEY `idx_sys_oauth_config_enabled` (`enabled`),
  KEY `idx_sys_oauth_config_created_at` (`created_at`),
  KEY `idx_sys_oauth_config_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='第三方登录配置';


DROP TABLE IF EXISTS `sys_operation_log`;

CREATE TABLE `sys_operation_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `trace_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '链路ID，关联应用日志',
  `user_id` bigint unsigned DEFAULT NULL COMMENT '操作人ID',
  `username` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人用户名(冗余存储)',
  `role_codes` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人角色快照(逗号分隔)',
  `module` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属模块(取自sys_api.group)',
  `action` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作描述(取自sys_api.description)',
  `method` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'HTTP方法',
  `route` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '路由模板',
  `path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实际请求路径',
  `target_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标资源ID',
  `req_params` text COLLATE utf8mb4_unicode_ci COMMENT '请求参数(脱敏+截断)',
  `resp_params` text COLLATE utf8mb4_unicode_ci COMMENT '响应参数(脱敏+截断)',
  `status` bigint DEFAULT NULL COMMENT 'HTTP状态码',
  `biz_code` bigint DEFAULT NULL COMMENT '业务返回码',
  `success` tinyint(1) DEFAULT NULL COMMENT '是否成功',
  `error_msg` text COLLATE utf8mb4_unicode_ci COMMENT '失败信息',
  `client_ip` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '客户端IP',
  `user_agent` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-Agent',
  `latency_ms` bigint DEFAULT NULL COMMENT '耗时(毫秒)',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_operation_log_user_id` (`user_id`),
  KEY `idx_sys_operation_log_module` (`module`),
  KEY `idx_sys_operation_log_success` (`success`),
  KEY `idx_sys_operation_log_client_ip` (`client_ip`),
  KEY `idx_sys_operation_log_created_at` (`created_at`),
  KEY `idx_sys_operation_log_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=6389 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='操作审计日志，记录一次写操作（或登录/登出）';

































































DROP TABLE IF EXISTS `sys_role`;

CREATE TABLE `sys_role` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '编码',
  `sort` bigint DEFAULT '0' COMMENT '排序号',
  `status` tinyint DEFAULT '1' COMMENT '1-正常 0-禁用',
  `data_scope` tinyint NOT NULL DEFAULT '1' COMMENT '数据权限范围 1全部 3本部门 4本部门及子部门 5仅本人',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_role_code` (`code`),
  KEY `idx_sys_role_created_at` (`created_at`),
  KEY `idx_sys_role_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='角色';


DROP TABLE IF EXISTS `sys_role_menu`;

CREATE TABLE `sys_role_menu` (
  `sys_role_id` bigint unsigned NOT NULL COMMENT '角色ID',
  `sys_menu_id` bigint unsigned NOT NULL COMMENT '菜单ID',
  PRIMARY KEY (`sys_role_id`,`sys_menu_id`),
  KEY `fk_sys_role_menu_sys_menu` (`sys_menu_id`),
  CONSTRAINT `fk_sys_role_menu_sys_menu` FOREIGN KEY (`sys_menu_id`) REFERENCES `sys_menu` (`id`),
  CONSTRAINT `fk_sys_role_menu_sys_role` FOREIGN KEY (`sys_role_id`) REFERENCES `sys_role` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='角色-菜单关联表';











DROP TABLE IF EXISTS `sys_site_config`;

CREATE TABLE `sys_site_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `site_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '站点名称(企业名)',
  `logo_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Logo图片URL',
  `favicon_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Favicon图标URL',
  `hero_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页Hero大标题',
  `hero_subtitle` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页Hero副标题',
  `hero_badge` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页Hero小标签',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '站点描述(SEO meta description)',
  `theme` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前台主题包(dark-tech/light-clean)',
  `stats_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '首页数字带JSON',
  `modules_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '首页模块墙JSON',
  `modules_badge` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页优势区块徽章',
  `modules_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页优势区块标题',
  `modules_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页优势区块副标题',
  `cta_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页底部CTA标题',
  `cta_highlight` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页底部CTA高亮词',
  `cta_subtitle` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '首页底部CTA副标题',
  `contact_phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `contact_email` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系邮箱',
  `contact_address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司地址',
  `work_hours` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工作时间(如 周一至周五 9:00-18:00)',
  `icp_beian` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ICP备案号(如 京ICP备xxxxxxxx号)',
  `public_security_beian` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公安备案号',
  `public_security_beian_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公安备案跳转链接',
  `keywords` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SEO关键词(逗号分隔)',
  `analytics_code` text COLLATE utf8mb4_unicode_ci COMMENT '统计代码(GA/百度统计等JS)',
  `copyright` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '版权声明(如 © 2024 某某科技有限公司)',
  `mcp_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MCP服务地址',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  `geo_region` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT 'SEO地域码(如 CN-henan-luoyang,百度 geo.region)',
  `geo_placename` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT 'SEO地名(如 河南省洛阳市,geo.placename)',
  `geo_position` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT 'SEO坐标(纬度;经度,如 34.6197;112.4540,geo.position/ICBM)',
  `faq_json` text COLLATE utf8mb4_unicode_ci COMMENT '官网FAQ列表(JSON: [{q,a}],GEO问答结构,AI搜索引擎引用)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_site_config_created_at` (`created_at`),
  KEY `idx_sys_site_config_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='站点信息配置';


DROP TABLE IF EXISTS `sys_storage_config`;

CREATE TABLE `sys_storage_config` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `driver` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'local' COMMENT '存储驱动(local/oss)',
  `local_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT './storage/uploads' COMMENT '本地存储根目录',
  `resource_domain` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本地资源访问域名',
  `oss_endpoint` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS Endpoint',
  `oss_access_key_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS AccessKeyID',
  `oss_access_key_secret` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS AccessKeySecret(脱敏不返回)',
  `oss_bucket_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS Bucket名称',
  `oss_custom_domain` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'OSS 自定义域名/CDN',
  `max_upload_mb` bigint DEFAULT '20' COMMENT '单文件大小上限(MB)',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  PRIMARY KEY (`id`),
  KEY `idx_sys_storage_config_created_at` (`created_at`),
  KEY `idx_sys_storage_config_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='存储配置(本地/OSS)';


DROP TABLE IF EXISTS `sys_user`;

CREATE TABLE `sys_user` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `username` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户名(登录账号)',
  `password` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '密码',
  `nickname` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '昵称',
  `dept_id` bigint unsigned DEFAULT NULL COMMENT '部门ID(关联hrm_department)',
  `leader_id` bigint unsigned DEFAULT NULL COMMENT '直属上级ID(关联sys_user,审批SUPERIOR用)',
  `avatar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '头像',
  `email` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号',
  `status` tinyint DEFAULT '1' COMMENT '1-正常 0-禁用',
  `token_version` bigint DEFAULT '0' COMMENT '会话版本，自增使旧 token 失效',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间(软删除)',
  `wecom_user_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '企业微信UserID',
  `wechat_openid` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '微信服务号openid',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_sys_user_username` (`username`),
  KEY `idx_sys_user_created_at` (`created_at`),
  KEY `idx_sys_user_deleted_at` (`deleted_at`),
  KEY `idx_sys_user_wecom_user_id` (`wecom_user_id`),
  KEY `idx_sys_user_wechat_openid` (`wechat_openid`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统用户';


DROP TABLE IF EXISTS `sys_user_role`;

CREATE TABLE `sys_user_role` (
  `sys_user_id` bigint unsigned NOT NULL COMMENT '用户ID',
  `sys_role_id` bigint unsigned NOT NULL COMMENT '角色ID',
  PRIMARY KEY (`sys_user_id`,`sys_role_id`),
  KEY `fk_sys_user_role_sys_role` (`sys_role_id`),
  CONSTRAINT `fk_sys_user_role_sys_role` FOREIGN KEY (`sys_role_id`) REFERENCES `sys_role` (`id`),
  CONSTRAINT `fk_sys_user_role_sys_user` FOREIGN KEY (`sys_user_id`) REFERENCES `sys_user` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户-角色关联表';


SET FOREIGN_KEY_CHECKS = 1;
