INSERT INTO `crm_contract_template` (`id`, `name`, `content`, `remark`, `enabled`, `owner_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '软件服务合同（标准模板）', 'sadfas ${contractNo}${startDate}${stage}', '软件部署服务合同标准模板，含 ${变量} 占位符，套打时自动替换', 1, 1, '2026-08-04 20:07:00.209', '2026-08-06 16:15:16.052', NULL),
(2, '技术服务合同（标准模板）', '# 技术服务合同\n\n**合同编号：** ${contractNo}\n\n甲方（委托方）：${customerName}\n统一社会信用代码/税号：${taxNo}\n地址：${titleAddress}\n电话：${titlePhone}\n开户行：${bankName}\n银行账号：${bankAccount}\n\n乙方（服务方）：${titleName}\n地址：${titleAddress}\n电话：${titlePhone}\n\n## 第一条 服务内容\n\n甲方委托乙方提供技术服务，具体服务内容、技术指标及验收标准以双方确认的技术方案为准。\n\n## 第二条 服务期限\n\n本合同服务期限自 **${startDate}** 起至 **${endDate}** 止。合同期满前30日，双方可协商续签事宜。\n\n## 第三条 合同金额及支付方式\n\n1. 本合同技术服务总金额为 **¥${totalAmount}** 元（大写：人民币 元整），含税。\n2. 支付方式：按双方约定节点分期支付，具体如下：\n   - 合同签订后支付首付款；\n   - 服务验收合格后支付尾款。\n3. 甲方每次付款前，乙方应开具等额合法有效的增值税发票。\n\n## 第四条 双方权利义务\n\n### 4.1 甲方权利义务\n1. 及时向乙方提供开展技术服务所需的资料、数据及必要的配合；\n2. 按合同约定及时足额支付服务费用；\n3. 对乙方提供的服务成果及时组织验收。\n\n### 4.2 乙方权利义务\n1. 按约定时间、标准完成技术服务并交付成果；\n2. 对甲方提供的资料、数据保密，未经甲方书面同意不得向第三方披露；\n3. 保证服务成果不侵犯任何第三方知识产权。\n\n## 第五条 验收\n\n服务完成后，甲方应在 **7个工作日** 内组织验收。逾期未验收且未提出书面异议的，视为验收合格。\n\n## 第六条 违约责任\n\n1. 乙方未按约定提供服务或服务成果不合格的，应负责整改直至合格，逾期超过15日的，甲方有权解除合同并要求退还相应款项；\n2. 甲方逾期付款的，每逾期一日按未付款项的 **0.05%** 支付违约金；\n3. 任何一方违反保密义务给对方造成损失的，应承担赔偿责任。\n\n## 第七条 知识产权\n\n服务过程中产生的技术成果及知识产权归属，按双方另行签订的知识产权协议约定执行；未约定的，依相关法律法规确定。\n\n## 第八条 保密条款\n\n双方对本合同内容及履行过程中知悉的对方商业秘密负有保密义务，保密期限自合同生效之日起 **3年**。\n\n## 第九条 争议解决\n\n因本合同引起的争议，双方应友好协商解决；协商不成的，任何一方均可向 **乙方所在地** 人民法院提起诉讼。\n\n## 第十条 其他\n\n1. 本合同一式 **贰** 份，甲乙双方各执 **壹** 份，具有同等法律效力；\n2. 本合同自双方签字（盖章）之日起生效；\n3. 未尽事宜，双方可签订补充协议，补充协议与本合同具有同等法律效力。\n\n甲方（盖章）：${customerName}    乙方（盖章）：${titleName}\n\n授权代表：                    授权代表：\n\n签订日期：${signedDate}    签订日期：${signedDate}\n', '技术服务合同标准模板，含 ${变量} 占位符，套打时自动替换', 1, 1, '2026-08-06 13:04:46.859', '2026-08-06 13:04:46.859', NULL),
