(136, 'AI 编程案例展示官网', 'PRJ-20261016-073', '前端', '项目', 0.00, NULL, 2, NULL, '**项目定位**：AI 编程案例展示网站，含 AI Agent Hub 案例页。\n\n- **技术栈**：Web 前端\n- **我的参与**：4 次提交，2026-03\n- **范围**：案例展示页', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(137, '职业性格测试 Web 应用', 'PRJ-20261016-074', '全栈', '项目', 0.00, NULL, 2, 'https://cdn.devlovecode.com/product/cover/7d280ab72d5e4ed826f657969d51a8cb.png', '个性与职业倾向测试类 Web 应用，从既有 Stitch 设计稿项目改造落地：测评流程与作答体验、测试结果页与展示。\n\n**核心功能**\n- 测评流程与作答体验\n- 测试结果页与展示\n\n**技术要点**：Web\n**我的参与**：8 次提交，2026-04\n\n适合作为「有设计稿、要快速落成可用 Web 应用」的样例——从设计稿到上线的转化，正是河南爱编程从 0 到 1 服务的常见形态。', '2026-10-16 10:11:41', '2026-10-22 17:20:07.904', NULL),
(138, 'huolande 微信小程序', 'PRJ-20261016-076', '小程序', '项目', 0.00, NULL, 2, NULL, '**项目定位**：huolande 业务微信小程序，支持海报绘制小程序码。\n\n- **技术栈**：微信原生小程序\n- **我的参与**：8 次提交，2026-04\n- **范围**：海报与分享能力', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(139, '微信小程序原型', 'PRJ-20261016-077', '小程序', '项目', 0.00, NULL, 2, NULL, '**项目定位**：微信小程序原型工程。\n\n- **技术栈**：微信原生小程序\n- **我的参与**：1 次提交，2025-10（初始工程）\n- **范围**：原型', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(140, '个人 iOS 应用工程', 'PRJ-20261016-078', 'iOS', '项目', 0.00, NULL, 2, NULL, '**项目定位**：个人 iOS 应用工程（起点项目）。\n\n- **技术栈**：Swift\n- **我的参与**：1 次提交，2023-11（工程初始化）\n- **范围**：iOS 工程', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(141, 'Keepsake iOS 应用（原型）', 'PRJ-20261016-079', 'iOS', '项目', 0.00, NULL, 2, NULL, '**项目定位**：Keepsake iOS 应用原型。\n\n- **技术栈**：Swift\n- **我的参与**：1 次提交，2026-04（工程初始化）\n- **范围**：原型', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(142, '图片管理工具（Rust）', 'PRJ-20261016-080', '桌面端', '项目', 0.00, NULL, 2, NULL, '**项目定位**：图片管理桌面工具。\n\n- **技术栈**：Rust\n- **我的参与**：23 次提交，2026-04\n- **范围**：图片管理', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(143, 'Linux 服务器管理面板（Rust TUI）', 'PRJ-20261016-081', '桌面端', '项目', 0.00, NULL, 2, NULL, '**项目定位**：现代化 Linux 服务器管理面板，极简 TUI（概览 + 服务管理 + 智能安装助手）。\n\n- **技术栈**：Rust（TUI）\n- **我的参与**：25 次提交，2026-02 ~ 2026-03\n- **范围**：概览、服务管理、安装助手', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL);
INSERT INTO `crm_product` (`id`, `name`, `product_no`, `category`, `unit`, `standard_price`, `cost_price`, `status`, `image_url`, `description`, `created_at`, `updated_at`, `deleted_at`) VALUES
(144, 'MirrorGrid 桌面原型', 'PRJ-20261016-082', '桌面端', '项目', 0.00, NULL, 2, NULL, '**项目定位**：高密度网格展示的桌面原型应用。\n\n- **技术栈**：Rust\n- **我的参与**：1 次提交，2026-07（原型）\n- **范围**：原型验证', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(145, 'AI 优先 CMS（CLI 驱动）', 'PRJ-20261016-083', '全栈', '项目', 0.00, NULL, 2, NULL, '**项目定位**：面向 AI 时代的 CMS，核心特色是提供 CLI，让 AI agent（或人类）通过命令行发布与管理文章。\n\n- **技术栈**：Go + CLI\n- **我的参与**：6 次提交，2026-07\n- **范围**：CLI 内容管理', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(146, '悟空CRM Go 改造骨架', 'PRJ-20261016-084', '全栈', '项目', 0.00, NULL, 2, NULL, '**项目定位**：悟空CRM 的 Go + React 技术栈改造骨架。\n\n- **技术栈**：Go + React\n- **我的参与**：6 次提交，2026-04\n- **范围**：改造骨架', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(147, '思源笔记 Go 改造版', 'PRJ-20261016-085', '全栈', '项目', 0.00, NULL, 2, NULL, '**项目定位**：思源笔记的 Go 服务端改造（server + admin + 前端分仓）。\n\n- **技术栈**：Go\n- **我的参与**：4 次提交，2026-04\n- **范围**：服务端改造', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(148, 'qitan 多租户系统', 'PRJ-20261016-086', '全栈', '项目', 0.00, NULL, 2, NULL, '**项目定位**：多租户业务系统，含多租户权限与菜单适配。\n\n- **技术栈**：Go\n- **我的参与**：24 次提交，2026-06\n- **范围**：多租户权限与访问控制', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(149, '短剧出海 B2B 工作台', 'PRJ-20261016-087', '全栈', '项目', 0.00, NULL, 2, 'https://cdn.devlovecode.com/product/cover/4b577357a6d969bde92bfea494d8e289.png', '短剧出海本地化的 B2B Web 工作台：覆盖短剧内容与本地化流程的协作管理，并完成前端工程 ESM 化改造。\n\n**核心功能**\n- 短剧内容与本地化流程的协作工作台\n- 前端工程 ESM 化改造\n\n**技术要点**：Go · Web\n**我的参与**：3 次提交，2026-06\n\n剧集约排、翻译进度、分发状态等多角色协作需求在这里收敛成一条流程，可作为内容出海类 SaaS 的协作底座参考。', '2026-10-16 10:11:41', '2026-10-22 17:20:07.904', NULL),
(150, '养老服务系统（Go）', 'PRJ-20261016-088', '后端', '项目', 0.00, NULL, 2, 'https://cdn.devlovecode.com/product/cover/dda510e56720b6d217b67b170dfa185c.png', '养老服务方向的业务系统后端：养老业务建模与接口实现，Go 工程底座搭建。\n\n**核心功能**\n- 养老业务建模与接口实现\n- Go 工程底座搭建\n\n**技术要点**：Go\n**我的参与**：29 次提交，2026-03\n\n建档、服务派单、健康记录等业务对象完成领域建模并暴露为 API，可对接小程序端或第三方系统。Go 单二进制部署对资源敏感的政企/社区场景友好，2 核 4G 服务器即可运行。', '2026-10-16 10:11:41', '2026-10-22 17:20:07.905', NULL),
(151, 'Telegram 群组管理 Bot', 'PRJ-20261016-089', '工具', '项目', 0.00, NULL, 2, NULL, '**项目定位**：为提升群组操作效率自研的 Telegram 群组管理工具（we_group_bot 增强版）。\n\n- **技术栈**：Bot 开发\n- **我的参与**：26 次提交，2024-10 ~ 2024-11\n- **范围**：群组管理命令', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(152, 'Excel 生成工具（Java）', 'PRJ-20261016-090', '工具', '项目', 0.00, NULL, 2, NULL, '**项目定位**：Excel 文件生成小工具。\n\n- **技术栈**：Java\n- **我的参与**：1 次提交，2024-06\n- **范围**：Excel 构建', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(153, '图片水印工具（Java）', 'PRJ-20261016-091', '工具', '项目', 0.00, NULL, 2, NULL, '**项目定位**：图片加文字水印小工具。\n\n- **技术栈**：Java\n- **我的参与**：1 次提交，2025-04\n- **范围**：水印处理', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(154, 'Spring Boot 开源示例集', 'PRJ-20261016-092', '工具', '项目', 0.00, NULL, 2, NULL, '**项目定位**：各类开源项目的集成示例与学习工程。\n\n- **技术栈**：Spring Boot\n- **我的参与**：13 次提交，2023-06 ~ 2024-09\n- **范围**：示例集成', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(155, 'CCometixLine（开源贡献）', 'PRJ-20261016-093', '工具', '项目', 0.00, NULL, 2, NULL, '**项目定位**：高性能终端状态栏工具，本人贡献 context-window API 支持分支。\n\n- **技术栈**：Rust\n- **我的参与**：5 次提交，2026-01\n- **范围**：context window API 支持', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(156, 'AEO 销售话术与报告工具集', 'PRJ-20261016-094', '工具', '项目', 0.00, NULL, 2, 'https://cdn.devlovecode.com/product/cover/f93ebf842215cf32dcb68a1f43068f96.png', '面向 AI 搜索优化（AEO/GEO）的销售工具集：上门与电话双场景的陌拜话术结构化沉淀，配套 AEO 检测脚本——分析目标站点在 AI 引擎中的可见性并生成报告。\n\n**核心功能**\n- 上门与电话双场景陌拜话术结构化沉淀\n- AEO 检测脚本：分析目标站点在 AI 引擎中的可见性并生成报告\n\n**技术要点**：Python · AEO 优化\n**我的参与**：2026-08\n\n这个工具集正是本站 GEO 实践的内部武器：官网自身的 AI 可见性优化（llms.txt、Markdown 镜像、FAQPage schema）就用了其中的检测思路。', '2026-10-16 10:11:41', '2026-10-22 17:20:07.906', NULL),
(157, 'TG 推广落地页工具', 'PRJ-20261016-095', '工具', '项目', 0.00, NULL, 2, NULL, '**项目定位**：TG 推广方向的落地页工具。\n\n- **技术栈**：Web\n- **我的参与**：3 次提交，2025-10\n- **范围**：落地页', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(158, '肉鸽游戏战斗原型', 'PRJ-20261016-096', '原型', '项目', 0.00, NULL, 2, NULL, '**项目定位**：肉鸽（roguelike）游戏的战斗演示原型。\n\n- **技术栈**：Web\n- **我的参与**：3 次提交，2026-04\n- **范围**：战斗演示与 UI 打磨', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(159, '常用服务 Docker 编排集', 'PRJ-20261016-097', '运维', '项目', 0.00, NULL, 2, NULL, '**项目定位**：常用中间件与服务的 Docker Compose 编排集合。\n\n- **技术栈**：Docker\n- **我的参与**：18 次提交，2023-03 ~ 2025-04\n- **范围**：部署编排', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(160, 'CRM Docker 化部署方案', 'PRJ-20261016-098', '运维', '项目', 0.00, NULL, 2, NULL, '**项目定位**：CRM 系统的 Docker 化部署编排方案。\n\n- **技术栈**：Docker\n- **我的参与**：37 次提交，2023-04 ~ 2024-02\n- **范围**：CRM 容器化部署', '2026-10-16 10:11:41', '2026-10-16 10:11:41', NULL),
(161, 'K12 校园学分与宠物养成 SaaS', 'PRJ-20261016-099', '全栈', '项目', 0.00, NULL, 2, 'https://cdn.devlovecode.com/product/cover/2785759b51e9240eb9b64488ff46ff8c.png', '面向 K12 校园场景的学分激励与宠物养成 SaaS：学生完成学分任务、养成虚拟宠物、记录成长，老师在管理端配置学分规则与任务，服务端管理学分体系与养成状态。\n\n**核心功能**\n- 微信原生小程序端：学分任务、宠物养成、成长记录\n- 管理端：学分规则与任务配置\n- 服务端：学分体系与养成状态管理\n\n**技术要点**：微信原生小程序 · 服务端\n**我的参与**：2026-09 启动\n\n「学分 + 游戏化养成」的激励机制可复用到企业培训、会员成长等需要持续激励的场景。', '2026-10-16 10:11:41', '2026-10-22 17:20:07.907', NULL);
