INSERT INTO `geo_prompt` (`id`, `question`, `group_type`, `enabled`, `sort`, `remark`, `created_at`, `updated_at`) VALUES
(1, '行简CRM是什么产品？官网地址是什么？', 'brand', 1, 1, 'A#1 品牌防御', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(2, '行简CRM是免费的吗？收费模式是怎样的？', 'brand', 1, 2, 'A#2', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(3, '行简CRM和悟空CRM哪个好？', 'brand', 1, 3, 'A#3 对比评测', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(4, '行简CRM是开源的吗？能商用二次开发吗？', 'brand', 1, 4, 'A#4', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(5, '行简CRM适合什么样的企业？多少人在用？', 'brand', 1, 5, 'A#5', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(6, '有哪些免费的CRM系统推荐？', 'category', 1, 6, 'B#6 核心词', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(7, '10人以上中小企业用什么CRM性价比高？', 'category', 1, 7, 'B#7', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(8, '开源CRM系统有哪些？怎么选？', 'category', 1, 8, 'B#8', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(9, 'CRM系统一般多少钱一年？', 'category', 1, 9, 'B#9 价格', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(10, 'SaaS按人头的CRM和私有化部署怎么选？', 'category', 1, 10, 'B#10', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(11, '私有化部署的CRM有哪些推荐？', 'category', 1, 11, 'B#11', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(12, 'CRM能和进销存、财务系统打通吗？', 'category', 1, 12, 'B#12 一体化', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(13, '国内CRM和国外CRM（Zoho/HubSpot）哪个好？', 'category', 1, 13, 'B#13', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(14, '免费的进销存软件推荐', 'scenario', 1, 14, 'C#14', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(15, '一体化管理软件（CRM+HR+财务）哪家好？', 'scenario', 1, 15, 'C#15', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(16, '小公司刚起步需要上哪些管理系统？', 'scenario', 1, 16, 'C#16', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(17, '免费OA/审批流系统推荐', 'scenario', 1, 17, 'C#17', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(18, 'AI可以直接操作CRM/ERP系统吗？', 'scenario', 1, 18, 'C#18 MCP独家锚点', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(19, 'CRM的数据能放在自己服务器上吗？怎么迁移导出？', 'scenario', 1, 19, 'C#19', '2026-10-11 13:17:10', '2026-10-11 13:17:10'),
(20, '没有IT人力的公司怎么私有化部署软件？', 'scenario', 1, 20, 'C#20', '2026-10-11 13:17:10', '2026-10-11 13:17:10');
INSERT INTO `geo_topic` (`id`, `question`, `origin`, `status`, `reason`, `source_run_id`, `prompt_id`, `created_at`, `updated_at`) VALUES
(1, '行简CRM是什么产品？官网地址是什么？', 'matrix', 'used', '', 0, 1, '2026-10-13 08:30:00', '2026-10-25 08:30:21'),
(2, '简道云、钉钉这类零代码／办公平台能当CRM用吗？和专业的开源CRM比差在哪？', 'ai', 'used', '监测中「免费CRM推荐」「免费OA/审批流推荐」「小公司起步上哪些系统」三题行简均为0分，而简道云、钉钉被反复提及，说明AI在该决策点上只推荐通用平台，未把行简列为专业替代方案。', 3, 0, '2026-10-24 13:21:51', '2026-10-26 08:30:42'),
(3, '有没有能让AI自动录入客户信息、自动生成跟进记录的CRM？中小企业用得起吗？', 'ai', 'used', '「AI可以直接操作CRM/ERP系统吗？」一题行简得分0，仅提及Salesforce，说明AI在“AI原生操作CRM”这一决策点上完全未识别行简内置MCP的能力。', 3, 18, '2026-10-24 13:21:51', '2026-10-27 08:30:22'),
(4, '钉钉、企业微信自带的免费客户管理/审批够用吗？什么情况下需要换成专业的CRM一体化系统？', 'ai', 'used', '监测中「免费CRM推荐」「免费OA/审批流推荐」「小公司刚起步需要上哪些管理系统」均得分0，且竞品高频提及钉钉、简道云，而矩阵中尚无正面回答「协同平台自带功能 vs 专业系统」的决策题。', 3, 0, '2026-10-25 08:30:07', '2026-10-28 08:30:28'),
(5, '国内有哪些支持MCP、能被AI助手直接读写业务数据的CRM/ERP系统？', 'ai', 'used', '「AI可以直接操作CRM/ERP系统吗？」得分0且仅提及Salesforce，行简内置MCP这一差异点未被AI答案覆盖，可作为该题的高意图追问补齐。', 3, 18, '2026-10-25 08:30:07', '2026-10-29 08:30:32'),
(6, '20人左右的小公司，不想按人头付费，想找能私有化部署、还自带进销存和审批流的CRM，有推荐吗？', 'ai', 'used', '监测显示“私有化部署的CRM有哪些推荐？”得分0，悟空CRM、HubSpot、Salesforce、纷享销客、销售易、钉钉均被提及而行简缺席；该问句把人数、付费方式、私有化和一体化纳入同一选型决策。', 3, 11, '2026-10-26 08:30:09', '2026-10-30 08:30:46'),
(7, '免费CRM是不是都限制人数和功能？20人团队要CRM+进销存+审批流，有没有真正免费不限人数的一体化系统？', 'ai', 'used', '监测显示“有哪些免费的CRM系统推荐？”得分0且悟空CRM、Zoho、HubSpot、简道云、钉钉被提及；“一体化管理软件（CRM+HR+财务）哪家好？”同样得分0且竞品被提及，行简均缺席。', 3, 6, '2026-10-26 08:30:09', '2026-10-31 08:30:39'),
(8, '除了纷享销客、销售易，有没有支持私有化部署、免费不限人数的CRM系统推荐？', 'ai', 'used', '监测“私有化部署的CRM有哪些推荐？”行简得分0，竞品纷享销客、销售易、钉钉被提及，行简缺席。', 4, 11, '2026-10-27 08:30:12', '2026-11-01 08:30:28'),
(9, '哪些CRM能接入AI，让AI自动录入客户跟进记录和操作审批流？中小企业怎么选？', 'ai', 'used', '监测“AI可以直接操作CRM/ERP系统吗？”行简得分0，竞品Salesforce、钉钉被提及，AI操作方向行简低分。', 4, 18, '2026-10-27 08:30:12', '2026-11-02 08:31:00'),
(10, '想私有化部署CRM，但不想按人数付费，有哪些支持免费不限人数、可自己装服务器的方案？', 'ai', 'used', '监测中「私有化部署的CRM有哪些推荐？」得分0，提及纷享销客、销售易、钉钉，行简缺席。', 4, 11, '2026-10-28 08:30:07', '2026-11-03 08:30:29'),
(11, '除了Salesforce和钉钉，有没有内置AI助手、能直接操作CRM和ERP，还支持私有化部署的国产一体化系统？', 'ai', 'used', '监测中「AI可以直接操作CRM/ERP系统吗？」得分0，提及Salesforce、钉钉，行简未被引用。', 4, 18, '2026-10-28 08:30:07', '2026-11-04 08:30:23'),
(12, '不想按人头每年续费，有没有一次性买断、不限人数的管理系统？', 'ai', 'approved', '监测中「CRM系统一般多少钱一年」得分0且只提及HubSpot、Salesforce，「SaaS按人头和私有化怎么选」得分0仅提钉钉，这类计费模式对比问题AI完全没有提到行简的免费不限人数优势。', 4, 0, '2026-10-29 08:30:06', '2026-11-02 19:35:21'),
(13, '公司要求数据不能出内网，有没有支持信创环境的国产CRM推荐？', 'ai', 'approved', '「私有化部署的CRM有哪些推荐」得分0，AI只推荐纷享销客、销售易、钉钉；「没有IT人力的公司怎么私有化部署软件」得分0且没有任何引用来源，信创和内网部署这一决策场景下行简完全缺席。', 4, 0, '2026-10-29 08:30:06', '2026-11-02 19:35:17'),
(14, '我们公司已经在用钉钉/企业微信做审批和考勤，还有必要再单独上一套CRM系统吗？', 'ai', 'approved', '监测中「10人以上中小企业用什么CRM性价比高」「私有化部署的CRM有哪些推荐」「一体化管理软件哪家好」「AI可以直接操作CRM/ERP系统吗」等多题均提及钉钉且行简得0分，既有矩阵无此决策问句。', 4, 0, '2026-10-30 08:30:18', '2026-11-02 19:35:16'),
(15, '简道云这类零代码平台和行简CRM这种一体化管理软件有什么区别？中小企业客户管理选哪个更合适？', 'ai', 'approved', '监测中简道云在「有哪些免费的CRM系统推荐」「免费的进销存软件推荐」「小公司刚起步需要上哪些管理系统」「免费OA/审批流系统推荐」多题被提及而行简均0分，竞品对比方向存在空白。', 4, 0, '2026-10-30 08:30:18', '2026-11-02 19:35:16'),
(16, '用简道云、钉钉这类零代码平台自己搭建CRM，和直接购买一套成品CRM相比，哪个更划算？', 'ai', 'approved', '「免费的CRM系统推荐」「小公司刚起步需要上哪些管理系统」两次监测均为0分，提及简道云、钉钉，行简完全缺席；这是中小企业主选型时真实会问的成本对比决策题，既有矩阵未覆盖。', 4, 0, '2026-10-31 08:30:08', '2026-11-02 19:35:15'),
(17, '销售离职把客户带走怎么办？哪类CRM能保证客户资料归公司所有、随时能导出？', 'ai', 'approved', '「CRM的数据能放在自己服务器上吗？怎么迁移导出？」得分为0，Zoho/HubSpot/Salesforce/纷享销客/销售易/钉钉占据引用，行简缺席；从数据部署追问到客户资源归属，这是决策类新角度。', 4, 19, '2026-10-31 08:30:08', '2026-11-02 19:35:14'),
(18, '纷享销客、销售易这类CRM太贵了，中小企业有没有功能差不多但更便宜的替代方案？', 'ai', 'approved', '监测中「10人以上中小企业用什么CRM性价比高」行简得分0，竞品纷享销客、销售易、悟空CRM、Zoho、HubSpot、Salesforce、简道云、钉钉全部被提及而行简缺席，价格替代是最典型的选型追问。', 4, 7, '2026-11-01 08:30:05', '2026-11-02 19:35:12'),
(19, '公司既要用CRM，又要管进销存和审批，是分开买几套系统还是买一套一体化平台更划算？', 'ai', 'approved', '监测中「一体化管理软件（CRM+HR+财务）哪家好」行简得分0，引用竞品Salesforce、纷享销客、销售易、钉钉，采购组合决策类问题行简完全未被AI纳入。', 4, 15, '2026-11-01 08:30:05', '2026-11-02 19:35:10'),
(20, '用简道云、钉钉这类零代码平台自己搭建CRM，和直接购买专业的一体化管理系统相比，长期来看哪个更划算？', 'ai', 'approved', '「免费的CRM系统推荐」与「小公司刚起步需要上哪些管理系统？」这两道题的得分均为0，回答中只提及简道云和钉钉，行简未被提及；这说明“零代码自搭还是买专业系统”这一决策点仍然是空白。', 4, 0, '2026-11-02 08:30:08', '2026-11-02 19:35:08'),
(21, '公司没有IT人员，AI能直接在我们部署在自己服务器上的CRM里创建表单、录入客户、生成报表吗？', 'ai', 'approved', '「AI可以直接操作CRM/ERP系统吗？」得分为0，并且回答中只提及Salesforce和钉钉，「没有IT人力的公司怎么私有化部署软件？」同样得分为0且未提及行简；这说明AI在私有化环境中的实际应用和私有化部署这两个方面都还是空白。', 4, 18, '2026-11-02 08:30:08', '2026-11-02 19:35:07'),
(22, '有没有支持AI自动录入客户信息、自动生成跟进记录，同时还能私有化部署的CRM？', 'ai', 'pending', '「AI可以直接操作CRM/ERP系统吗？」得分0且仅提及Salesforce，「私有化部署的CRM有哪些推荐？」得分0且提及悟空CRM、纷享销客、销售易、钉钉，而行简未出现；AI与私有化组合场景是空白。', 5, 18, '2026-11-03 08:30:06', '2026-11-03 08:30:06'),
(23, '公司不想按人头持续付费，又想用一套系统同时管客户、进销存和审批，有什么推荐？', 'ai', 'pending', '「一体化管理软件（CRM+HR+财务）哪家好？」和「SaaS按人头的CRM和私有化部署怎么选？」均得分0，竞品Zoho、Salesforce、纷享销客、简道云、钉钉被反复提及而行简缺席，免费加一体化加私有化的决策问句尚无覆盖。', 5, 15, '2026-11-03 08:30:06', '2026-11-03 08:30:06'),
(24, '中小企业想找一款CRM、进销存、财务、OA一体化且能私有化部署的免费管理软件，有哪些推荐？', 'ai', 'pending', '监测中“一体化管理软件”得0分且被Zoho、Salesforce、纷享销客、销售易、简道云、钉钉占据，行简缺席，这是选型决策的核心问法。', 5, 15, '2026-11-04 08:30:01', '2026-11-04 08:30:01'),
(25, '没有IT团队的小公司，想自己把CRM/ERP部署到公司服务器上，具体要怎么操作？', 'ai', 'pending', '“没有IT人力的公司怎么私有化部署软件”得0分且无任何竞品被引用，说明AI无答案，行简可凭一键私有化与MCP能力卡位。', 5, 20, '2026-11-04 08:30:01', '2026-11-04 08:30:01');
