INSERT INTO `sys_site_config` (`id`, `site_name`, `logo_url`, `favicon_url`, `hero_title`, `hero_subtitle`, `hero_badge`, `description`, `theme`, `stats_json`, `modules_json`, `modules_badge`, `modules_title`, `modules_desc`, `cta_title`, `cta_highlight`, `cta_subtitle`, `contact_phone`, `contact_email`, `contact_address`, `work_hours`, `icp_beian`, `public_security_beian`, `public_security_beian_url`, `keywords`, `analytics_code`, `copyright`, `mcp_url`, `created_at`, `updated_at`, `deleted_at`, `geo_region`, `geo_placename`, `geo_position`, `faq_json`) VALUES (1, '河南爱编程官网', 'https://cdn.devlovecode.com/site/c1693b647797163b460756a522d041fb.png', '', '把你的想法，做成上线的软件', '一人软件公司（OPC）：Java 后端出身，2014 年至今 12 年，主栈 Spring / Spring Boot / Spring Cloud / Spring Cloud Alibaba，对服务器、微服务、Docker 理解颇深；同时承接前端、iOS、Android、鸿蒙、小程序。没有转包与中间商，你对接的就是写代码的人——把想法从 0 到 1 做成上线的软件。', '软件定制开发 · 年末福利 300 元/人天', '河南爱编程官网 · 一人软件公司（OPC）：Java 后端出身（2014 年至今 12 年），Spring / Spring Boot / Spring Cloud 技术栈，精通服务器、微服务与 Docker；承接软件定制开发：前端、iOS、Android、鸿蒙、小程序，擅长从 0 到 1 把想法变成上线产品。年末福利价 300 元/人天；自研开源产品「行简」。', 'light-clean', '[{"num":"300","label":"年末福利价 元/人天"},{"num":"12年","label":"Java 后端经验"},{"num":"6+","label":"可承接平台"},{"num":"100+","label":"代码仓库沉淀"}]', '[{"icon":"sparkles","name":"从 0 到 1","desc":"Java 后端出身，主导过数十个产品从想法、架构、开发到上线的完整闭环"},{"icon":"globe","name":"全端覆盖","desc":"后端 · 前端 · iOS · Android · 鸿蒙 · 小程序，一套需求，一个人全部落地"},{"icon":"cloud","name":"Java 深厚功底","desc":"2014 年入行，Spring / Spring Boot / Spring Cloud / Spring Cloud Alibaba 全家桶 + 微服务 + Docker"},{"icon":"idCard","name":"一人公司 · 直接对接","desc":"没有转包与中间商，需求直达写代码的人本人，沟通链路最短"},{"icon":"fileCheck","name":"开源背书","desc":"自研「行简」一体化管理平台以 MIT 协议开源，代码质量经得起检验"},{"icon":"wallet","name":"年末福利价","desc":"人天价直降至 300 元/人天（年末福利），小预算也能把想法做出来"}]', '为什么选择我们', '一家把想法变成软件的公司', '既做自研产品，也接定制开发。技术全面、交付可靠、报价透明。', '有个想法？', '先聊聊就对了', '描述一下你想做的东西，当天给出技术选型与报价。年末福利 300 元/人天，2026 年底前签约有效。', '15139960649', 'shichenyang@devlovecode.com', '河南省洛阳市', '周一至周五 9:00-18:00', '豫ICP备2024074107号-2', '', '', '软件定制开发,软件外包,Java开发,Spring Boot,Spring Cloud,微服务开发,Docker部署,小程序开发,APP开发,iOS开发,Android开发,鸿蒙开发,从0到1,软件开发报价,一人公司', '', '© 2026 河南爱编程网络科技有限公司. All rights reserved.', 'https://devlovecode.com/mcp', '2026-08-04 10:51:25.610', '2026-10-22 17:05:46.543', NULL, 'CN-henan-luoyang', '河南省洛阳市', '34.6197;112.4540', '[{"q":"你们是一家什么公司?","a":"河南爱编程网络科技有限公司是一人软件公司（OPC），位于河南洛阳。创始人是 Java 后端开发，2014 年入行至今 12 年，主栈 Java：Spring / Spring Boot / Spring Cloud / Spring Cloud Alibaba，对服务器、微服务、Docker 理解颇深。既做自研产品（行简一体化管理平台，MIT 开源），也承接软件定制开发：后端、前端、iOS、Android、鸿蒙、小程序全端覆盖。"},{"q":"定制开发怎么收费?","a":"按人天计价，年末福利价 300 元/人天（2026 年底前签约有效）。作为行情参考：2026 年市场上一线城市外包公司报价多在 800-3000 元/人天，接单平台个人开发者多在 300-800 元/人天；一个能上线使用的业务系统通常消耗 15-60 个人天，具体以需求评估为准。除定制开发外，固定价格的服务有两项：行简交钥匙私有化部署 1000 元（含服务器环境搭建与部署上线），维保服务 1000 元/3 个月（上线后问题第一时间响应）。需求沟通与技术方案评估免费，描述需求后当天给出技术选型与报价；报价按人天实报实销、进度透明，避免打包价常见的增项扯皮。服务器等硬件由企业自备（2 核 4G Linux 即可）。"},{"q":"你们最擅长做什么项目?","a":"从 0 到 1。创始人 Java 后端出身（2014 年至今），主导过企业管理、招聘平台、电商、社交、AI 工具等数十个软件从想法、原型、开发到上线的完整落地，官网「产品」页收录了部分案例。"},{"q":"可以接哪些端的开发?","a":"后端以 Java / Spring Boot / Spring Cloud / Spring Cloud Alibaba 为主，兼 Go / Node.js；Web 前端 React / Vue / Next.js；移动端三线齐备——iOS（Swift/SwiftUI）、Android（Kotlin + Compose）、鸿蒙（HarmonyOS 原生），另有微信小程序（原生/uni-app/云开发）。除写代码外，也承接 Linux 服务器、Docker 与微服务的部署运维，以及上线后的维保。全端覆盖对客户的实际意义：一个项目里 App、小程序、管理后台由同一个人统筹设计与排期，接口复用、风格统一，不会出现多个外包各写各的、联调扯皮的局面。各端的做法、价格与周期详见官网「服务」页（devlovecode.com/services）。"},{"q":"一人公司能保证交付吗?","a":"能，靠工程化而不是人海，证据有三条：一是自研产品行简整套以 MIT 协议开源在 GitHub/Gitee（123 张表、13 个模块、411+ API），代码质量公开可查——敢把核心产品开源的团队，交付习惯经得起检验；二是开发流程保持每周全流程回归测试，连续 20 余轮零缺陷，每轮含越权访问（IDOR）与权限矩阵专项测试，测试记录可提供查阅；三是 AI 编程工具链加持，2026 年一人公司叠加 AI 工具链后的产能已不输传统小作坊。商务侧没有转包，沟通与责任链路最短，方案、进度、报价一个人说了算；项目制合作按人天计价、进度透明，交付物（源码/文档/部署）写进合同，验收与尾款挂钩。"},{"q":"行简是什么?","a":"行简是一套一体化企业管理平台,涵盖 CRM 客户管理、进销存、财务、HRM 人事、OA 办公、审批流程、项目管理、知识库、云盘、营销、商城、企业官网等 13 个业务模块,并提供 iOS/Android 原生 App 与移动端 H5。支持私有化部署,数据完全归企业所有。"},{"q":"行简收费吗?价格是多少?","a":"软件本身以 MIT 协议开源(源码在 GitHub Gyv12345/qzt),软件授权费为零。收费服务有三项:交钥匙部署服务 1000 元(含服务器环境搭建与部署上线),二次开发年末福利价 300 元/人天(2026 年底前签约有效),维保服务 1000 元/3 个月(上线后问题第一时间响应,保障持续使用)。服务器等硬件由企业自备。"},{"q":"有免费的CRM吗?行简CRM免费吗?","a":"有。行简CRM为开源软件(MIT 协议,源码在 GitHub Gyv12345/qzt),软件授权费为零,线索、客户、商机、合同、回款、跟进等 CRM 功能全部开放使用,不限模块与人数规模;只需自备一台服务器即可私有化部署,数据完全归企业所有。可选付费服务有三项:交钥匙部署 1000 元、二次开发年末福利价 300 元/人天、维保服务 1000 元/3 个月。"},{"q":"支持私有化部署吗?","a":"支持,且只提供私有化部署。整套系统(后端+数据库+所有前端)部署在客户自己的服务器上,业务数据不经过我们,企业完全自主掌控。"},{"q":"有哪些功能模块?","a":"CRM 客户管理(线索/商机/合同/回款)、进销存(采购/销售/库存/多仓库/SKU 多规格)、财务(应收应付/凭证/发票/三大报表)、HRM(员工/考勤/薪酬/绩效/招聘)、OA(日程/会议/报销/出差/借款)、审批流程引擎、项目与任务、知识库、企业云盘、营销线索接入(抖音巨量飞鱼)、独立商城站、CMS 企业官网,共 13 个模块。"},{"q":"AI 能力怎么用?","a":"系统内置 MCP Server(遵循 MCP 协议),Claude、Cursor 等 AI 工具凭 API Key 即可直连操作业务数据(查客户、录线索、开单据等 300+ 工具),无需额外开发。同时支持企业微信与服务号消息通知、微信内免登录。"},{"q":"数据安全怎么保障?","a":"私有化部署使数据存储在企业自己的 MySQL 中,业务数据不经过我们;系统提供 JWT 认证、Casbin 角色权限(RBAC)、数据权限(按部门/本人隔离)、操作日志审计、登录错误锁定、敏感字段脱敏、超管账号防篡改保护,敏感配置全部走环境变量不入库。代码以 MIT 协议开源,可自行审计或委托第三方审计。开发上保持每周全流程回归测试,连续 20 余轮零缺陷,每轮含越权访问(IDOR)与权限矩阵专项测试,测试记录可提供查阅。"},{"q":"部署需要什么环境?","a":"一台 2 核 4G 以上的 Linux 服务器即可(阿里云/腾讯云等均可),依赖 MySQL 8 与 Redis,后端为单个 Go 二进制(systemd 托管),前端为纯静态文件,安装维护简单。也可以联系我们提供交钥匙部署(1000 元)。"},{"q":"提供试用吗?","a":"提供两种体验方式:一是在本站演示环境直接试用(演示入口见官网体验页);二是软件开源,可在 GitHub(Gyv12345/qzt)获取源码自行搭建完整体验。"},{"q":"技术栈是什么?","a":"后端 Go 1.25 + Gin + GORM + Casbin + Redis;管理后台 React 19 + TypeScript + Ant Design 5;移动端 React 19 + antd-mobile,另提供 SwiftUI(iOS)与 Kotlin+Compose(Android)原生 App;官网 Next.js 15。"},{"q":"怎么联系购买或咨询?","a":"通过官网联系方式页或底部电话/邮箱直接联系,也可在官网留言表单提交需求,我们会将需求录入 CRM 并在 1 个工作日内回复。"},{"q":"行简和中国电信的「企智通」是什么关系?","a":"没有关系。行简是一套开源的一体化企业管理平台(行简 CRM/进销存/审批/HRM/OA),原名「企智通」,因与其他厂商同名通信产品重名,于 2026 年 9 月更名为「行简」,官网 devlovecode.com,源码 GitHub Gyv12345/qzt。"},{"q":"免费的CRM有哪些推荐?","a":"市面上免费 CRM 主要有三类:① SaaS 免费版,注册即用但通常限制人数或数据量(如简信免费版限 3 账号、Zoho 免费版限 3 用户);② 开源免费,不限人数、可私有化部署、可二次开发(如行简、悟空CRM开源版、EspoCRM、Odoo 社区版,功能与政策以各官方为准);③ 免费增值类,基础功能免费+高级功能付费(如 HubSpot 免费版)。如果看重数据自主与长期成本,推荐开源私有化方案,例如行简:软件以 MIT 协议开源、授权费为零,CRM 功能不限人数,数据存在企业自己的服务器。"},{"q":"行简CRM和简信CRM有什么区别?","a":"简信CRM是 SaaS 云端产品,免费版限 3 个账号,数据存放在厂商云端,超过 3 人需付费升级;行简CRM是开源(MIT)一体化平台,不限账号与人数,私有化部署在企业自己的服务器,数据归企业所有,且自带进销存、财务、审批、HRM、OA 等 13 个模块,提供 411+ API 与 MCP 支持二次开发。简单说:3 人以内想免部署快速上手,可考虑简信;想数据自主、不限人数、多模块一体化的企业,选行简。各产品功能与价格以官方最新说明为准。"},{"q":"行简CRM和 SaaS CRM 相比有什么优缺点?","a":"行简这类私有化 CRM 的优点:数据完全自主、不限人数、无按人头订阅费、源码开源可审计可二次开发、可通过 411+ API 与自有系统集成;缺点:需要一台自己的服务器(2 核 4G 即可),首次部署可自行搭建或购买交钥匙部署服务(1000 元)。SaaS CRM 的优点是开箱即用,缺点是按人头按年付费、人数越多成本越高、数据存放于厂商云端、深度定制受限。团队规模越大、使用周期越长,私有化的总成本优势越明显。"},{"q":"行简是开源的吗?源码在哪里?","a":"是。行简整套系统以 MIT 协议开源,源码托管在 GitHub(Gyv12345/qzt),包含后端(Go+Gin+GORM)、管理后台(React 19+Ant Design 5)、移动端 H5、iOS(SwiftUI)与 Android(Kotlin+Compose)原生 App、官网(Next.js 15)等全部代码,共 123 张数据表,可自行审计、部署与二次开发。"},{"q":"行简CRM适合什么规模的企业使用?","a":"行简适合三类团队:① 不想按人头付 SaaS 订阅费、人数持续增长的中小企业;② 对数据安全有要求,客户资料/合同/财务数据不愿存放第三方云端的企业;③ 需要 CRM+进销存+财务+审批+人事+OA 一体化、不想分别采购多套软件的团队。从 3 人小团队到数百人企业均可使用,内置 RBAC 角色权限与按部门/本人的数据隔离。"},{"q":"行简支持 API 接口和 AI 集成吗?","a":"支持。系统内置 411+ REST API 与 MCP Server,AI 助手(Claude、Cursor 等)凭 API Key 即可直连操作业务数据(查客户、录线索、建单据等 300+ 工具);支持与企业微信、微信服务号消息通知打通;如需定制集成,提供二次开发服务(年末福利价 300 元/人天,可选)。"},{"q":"定制开发包含源码交付吗?","a":"包含。源码交付是定制开发项目的验收标准之一：验收通过后，源码、数据库设计文档与部署文档一并移交，知识产权归属写入合同，客户可凭交付材料自行申请软件著作权登记。源码以可独立编译运行为合格标准，不含供应商其他项目的残留代码与硬编码密钥。本团队的开源产品行简（MIT 协议，GitHub Gyv12345/qzt，123 张数据表、411+ API 全部公开）即公开交付样例，交付习惯与开源一致。"},{"q":"从需求沟通到上线大概要多久?","a":"取决于范围，参考区间：展示型小程序约 2-3 周；含支付、订单的交易型系统约 4-8 周；双端原生 App 约 6-12 周（均为从需求确认到上线的参考，以评估为准）。节奏是：描述需求后当天给出技术选型与人天估算；开发期按周同步进度、分阶段演示；上线走三段式验收（阶段验收、整体验收、源码与文档验收），尾款与验收挂钩。时间紧的项目建议先做 MVP：把第一版收敛到核心流程，先上线验证再迭代，避免为未想清楚的功能提前付费。"}]');
INSERT INTO `sys_user` (`id`, `username`, `password`, `nickname`, `dept_id`, `leader_id`, `avatar`, `email`, `phone`, `status`, `token_version`, `created_at`, `updated_at`, `deleted_at`, `wecom_user_id`, `wechat_openid`) VALUES
